def build_daemon_launch_command(port):
    port = int(port or DEFAULT_PORT)
    if getattr(sys, "frozen", False):
        executable = os.path.abspath(sys.executable)
        return [executable, "--daemon", f"--daemon-port={port}"], os.path.dirname(executable)
    script_path = os.path.abspath(__file__)
    return [sys.executable, script_path, "--daemon", f"--daemon-port={port}"], os.path.dirname(script_path)


def launch_daemon_subprocess(port):
    cmd, cwd = build_daemon_launch_command(port)
    return subprocess.Popen(
        cmd,
        cwd=cwd,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        **subprocess_kwargs_no_window(),
    )


def build_gateway_launch_command():
    if getattr(sys, "frozen", False):
        executable = os.path.abspath(sys.executable)
        return [executable, "--im-gateway"], os.path.dirname(executable)
    python_exe = get_python_executable()
    script_path = os.path.abspath(__file__)
    return [python_exe, script_path, "--im-gateway"], os.path.dirname(script_path)


def append_background_process_log(filename, message):
    try:
        log_dir = get_app_data_dir()
        os.makedirs(log_dir, exist_ok=True)
        log_path = os.path.join(log_dir, filename)
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        with open(log_path, "a", encoding="utf-8") as handle:
            handle.write(f"[{timestamp}] {message}\n")
    except Exception:
        pass


def log_startup_stage(stage, **fields):
    if not runtime_debug_logging_enabled():
        return
    elapsed_ms = int((time.monotonic() - STARTUP_STAGE_CLOCK) * 1000)
    parts = [f"stage={stage}", f"elapsed_ms={elapsed_ms}"]
    for key, value in fields.items():
        parts.append(f"{key}={value}")
    append_background_process_log(STARTUP_LOG_FILENAME, " ".join(parts))


def log_ui_exception(receiver, event, exception_text):
    receiver_name = type(receiver).__name__ if receiver is not None else "None"
    event_type = event.type() if event is not None else "None"
    append_background_process_log(
        UI_ERROR_LOG_FILENAME,
        f"receiver={receiver_name} event={event_type}\n{str(exception_text or '').rstrip()}",
    )


