def skill_center_tab_key(skill):
    if not isinstance(skill, dict):
        return "builtin"
    if str(skill.get("source_format") or "").strip() == SkillManager.MCP_SOURCE_FORMAT:
        return "mcp"
    if str(skill.get("source_type") or "").strip() == "bundled_plugin" or skill.get("type") == "bundled_plugin":
        return "optional"
    is_custom = skill.get("type") == "ai_generated" or skill.get("created_by") == "ai"
    return "custom" if is_custom else "builtin"


def skill_center_is_builtin(skill):
    return skill_center_tab_key(skill) == "builtin"


def skill_center_matches_filters(skill, query="", status_filter="all"):
    if not isinstance(skill, dict):
        return False
    enabled = bool(skill.get("enabled"))
    if status_filter == "enabled" and not enabled:
        return False
    if status_filter == "disabled" and enabled:
        return False
    normalized_query = str(query or "").strip().lower()
    if not normalized_query:
        return True
    haystack = " ".join(
        [
            str(skill.get("display_name") or ""),
            str(skill.get("name") or ""),
            str(skill.get("user_description") or ""),
            str(skill.get("description") or ""),
            " ".join(str(item) for item in (skill.get("tools") or [])),
            " ".join(str(item) for item in (skill.get("use_cases") or [])),
        ]
    ).lower()
    return normalized_query in haystack


SKILL_RUNTIME_RELOAD_PENDING_ATTR = "_skill_runtime_reload_pending"


def mark_skill_runtime_reload_pending(skill_manager, pending=True):
    if skill_manager is None:
        return
    setattr(skill_manager, SKILL_RUNTIME_RELOAD_PENDING_ATTR, bool(pending))


def skill_runtime_reload_pending(skill_manager):
    if skill_manager is None:
        return False
    return bool(getattr(skill_manager, "__dict__", {}).get(SKILL_RUNTIME_RELOAD_PENDING_ATTR, False))


def flush_pending_skill_runtime_reload(skill_manager):
    if not skill_runtime_reload_pending(skill_manager):
        return False
    skill_manager.load_skills()
    mark_skill_runtime_reload_pending(skill_manager, False)
    return True


def session_status_text(status, im_provider=None):
    if im_provider == "feishu":
        return ("来自飞书", DesignTokens.info_text, DesignTokens.info_bg)
    mapping = {
        "running": ("进行中", DesignTokens.info_text, DesignTokens.info_bg),
        "completed": ("已完成", DesignTokens.success_text, DesignTokens.success_bg),
        "interrupted": ("中断", DesignTokens.warning_text, DesignTokens.warning_bg),
        "error": ("异常", DesignTokens.error_text, DesignTokens.error_bg),
        "draft": ("新任务", DesignTokens.text_secondary, DesignTokens.bg_secondary),
    }
    return mapping.get(status or "draft", ("新任务", DesignTokens.text_secondary, DesignTokens.bg_secondary))


def summarize_tool_action(tool_name, args):
    args = args or {}
    name = tool_name or "tool"
    path = ""
    for key in ("path", "file_path", "src", "source", "target", "dst", "directory"):
        value = args.get(key)
        if isinstance(value, str) and value.strip():
            path = value.strip()
            break
    if name in {"text_file_read", "document_read"}:
        return "查看文件", path or "读取内容"
    if name in {"text_file_write", "text_file_update"}:
        return "更新文件", path or "写入结果"
    if name in {"workspace_rename_path"}:
        return "整理文件", path or "移动或重命名"
    if name in {"workspace_delete_path"}:
        return "删除文件", path or "删除项目"
    if name in {"workspace_list_files", "search_files", "glob", "grep", "search_codebase"}:
        return "扫描工作区", path or "查找相关文件"
    if name in {"bash", "run_command"}:
        cmd = args.get("command") or args.get("cmd") or ""
        return "执行命令", cmd[:48] if cmd else "运行系统命令"
    if name in {"request_user_approval"}:
        return "等待确认", "需要你决定下一步"
    if name in {"request_user_input"}:
        return "等待输入", "需要你补充信息"
    if name in {"publish_artifacts"}:
        return "交付产物", "准备交付文件或图片"
    return name.replace("_", " ").title(), path or "执行步骤"


def extract_related_paths(tool_name, args):
    if not isinstance(args, dict):
        return []
    paths = []
    for key in ("path", "file_path", "src", "source", "target", "dst", "directory"):
        value = args.get(key)
        if isinstance(value, str) and value.strip():
            paths.append(value.strip())
    if tool_name in {"text_file_write", "text_file_update", "workspace_rename_path", "workspace_delete_path"}:
        return paths
    return []


def preview_text(value, limit=220):
    text = str(value or "").replace("\r", " ").replace("\n", " ").strip()
    if len(text) <= limit:
        return text
    return text[: limit - 3] + "..."


def detail_text(value, limit=8000):
    text = str(value or "").strip()
    if len(text) <= limit:
        return text
    return text[:limit] + "\n\n...内容过长，已截断显示。"


def normalize_tool_arguments(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str) and value.strip():
        try:
            parsed = json.loads(value)
            if isinstance(parsed, dict):
                return parsed
        except Exception:
            return {"raw": value}
    return {}


def sub_agent_event_title(event):
    status = str((event or {}).get("status") or "").strip().lower()
    if status == "input":
        return "任务输入"
    if status == "thinking":
        return "思考"
    if status == "tool_use":
        return f"调用工具 · {event.get('tool_name') or 'unknown'}"
    if status == "tool_result":
        return f"工具结果 · {event.get('tool_name') or 'unknown'}"
    if status == "content":
        return "输出片段"
    if status == "provider_error":
        return "Provider 异常"
    if status in {"failed", "failed_recovered"}:
        return "执行失败"
    if status == "completed":
        return "最终输出"
    return status_label_text(status)


def sub_agent_event_summary(event):
    event = event or {}
    status = str(event.get("status") or "").strip().lower()
    if status == "input":
        return preview_text(event.get("input_text") or event.get("content"))
    if status == "thinking":
        return preview_text(event.get("reasoning_delta") or event.get("content"))
    if status == "tool_use":
        args = normalize_tool_arguments(event.get("tool_args"))
        action_title, action_detail = summarize_tool_action(event.get("tool_name") or "", args)
        return preview_text(action_detail or action_title)
    if status == "tool_result":
        duration = event.get("duration")
        duration_text = ""
        if duration not in (None, ""):
            try:
                duration_text = f" ({float(duration):.1f}s)"
            except Exception:
                duration_text = ""
        return preview_text((event.get("tool_result") or "") + duration_text)
    if status == "content":
        return preview_text(event.get("content_delta") or event.get("content"))
    if status == "provider_log":
        return preview_text(event.get("provider_message") or event.get("content"))
    if status == "provider_error":
        return preview_text(event.get("provider_message") or event.get("error") or event.get("content"))
    if status in {"failed", "failed_recovered", "killed", "closed"}:
        return preview_text(event.get("error") or event.get("content"))
    if status == "completed":
        return preview_text(event.get("output_text") or event.get("content"))
    return preview_text(
        event.get("content")
        or event.get("log_content")
        or event.get("task")
        or event.get("provider_message")
    )


def build_sub_agent_history_events(agent_row, messages):
    events = []
    agent_row = agent_row or {}
    agent_id = agent_row.get("id") or ""
    agent_name = agent_row.get("name") or ""
    terminal_status = agent_row.get("status") or "closed"
    last_role = ""
    tool_call_lookup = {}
    normalized_messages = [msg for msg in (messages or []) if isinstance(msg, dict)]
    for index, msg in enumerate(normalized_messages):
        if not isinstance(msg, dict):
            continue
        role = str(msg.get("role") or "").strip().lower()
        created_at = int(msg.get("created_at") or agent_row.get("updated_at") or time.time())
        if role == "user":
            events.append(
                {
                    "agent_id": agent_id,
                    "agent_name": agent_name,
                    "status": "input",
                    "event_type": "input",
                    "input_text": msg.get("content") or "",
                    "content": msg.get("content") or "",
                    "ts": created_at,
                    "from_history": True,
                }
            )
        elif role == "assistant":
            tool_calls = msg.get("tool_calls") if isinstance(msg.get("tool_calls"), list) else []
            for call in tool_calls:
                if not isinstance(call, dict):
                    continue
                fn = call.get("function") if isinstance(call.get("function"), dict) else {}
                events.append(
                    {
                        "agent_id": agent_id,
                        "agent_name": agent_name,
                        "status": "tool_use",
                        "event_type": "tool_call",
                        "tool_call_id": call.get("id") or "",
                        "tool_name": fn.get("name") or "",
                        "tool_args": normalize_tool_arguments(fn.get("arguments")),
                        "task": f"Tool: {fn.get('name') or 'unknown'}",
                        "ts": created_at,
                        "from_history": True,
                    }
                )
                tool_call_lookup[str(call.get("id") or "")] = {
                    "tool_name": fn.get("name") or "",
                    "tool_args": normalize_tool_arguments(fn.get("arguments")),
                }
            content = str(msg.get("content") or "").strip()
            if content:
                has_future_assistant = any(
                    str(item.get("role") or "").strip().lower() == "assistant"
                    and str(item.get("content") or "").strip()
                    for item in normalized_messages[index + 1 :]
                )
                status = "completed" if terminal_status == "completed" and not has_future_assistant else "content"
                events.append(
                    {
                        "agent_id": agent_id,
                        "agent_name": agent_name,
                        "status": status,
                        "event_type": "output" if status == "completed" else "content",
                        "content": content,
                        "output_text": content if status == "completed" else "",
                        "ts": created_at,
                        "from_history": True,
                    }
                )
        elif role == "tool":
            tool_meta = tool_call_lookup.get(str(msg.get("tool_call_id") or ""), {})
            events.append(
                {
                    "agent_id": agent_id,
                    "agent_name": agent_name,
                    "status": "tool_result",
                    "event_type": "tool_result",
                    "tool_call_id": msg.get("tool_call_id") or "",
                    "tool_name": tool_meta.get("tool_name") or "",
                    "tool_args": tool_meta.get("tool_args") or {},
                    "tool_result": msg.get("content") or "",
                    "tool_result_obj": msg.get("result_obj"),
                    "duration": ((msg.get("meta") or {}).get("duration") if isinstance(msg.get("meta"), dict) else None),
                    "content": msg.get("content") or "",
                    "ts": created_at,
                    "from_history": True,
                }
            )
        last_role = role

    if not events:
        summary = (agent_row.get("last_result") or agent_row.get("last_error") or "").strip()
        if summary:
            events.append(
                {
                    "agent_id": agent_id,
                    "agent_name": agent_name,
                    "status": terminal_status,
                    "event_type": terminal_status,
                    "content": summary,
                    "output_text": summary if terminal_status == "completed" else "",
                    "error": summary if terminal_status != "completed" else "",
                    "ts": int(agent_row.get("updated_at") or time.time()),
                    "from_history": True,
                }
            )
    return events

