class DrawerResizeHandle(QWidget):
    widthRequested = Signal(int)
    resizeFinished = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self._press_x = None
        self._start_width = 0
        self.setCursor(Qt.SizeHorCursor)
        self.setFixedWidth(8)
        self.setToolTip("拖动调整预览宽度")
        self.setStyleSheet("background: transparent; border: none;")

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._press_x = event.globalPosition().x()
            self._start_width = self.parentWidget().width() if self.parentWidget() else 0
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._press_x is not None:
            requested = self._start_width + int(self._press_x - event.globalPosition().x())
            self.widthRequested.emit(requested)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._press_x is not None:
            self._press_x = None
            self.resizeFinished.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)


class DeliverableWebPreview(QWidget):
    """Qt-owned scrolling shell for the embedded HTML deliverable preview."""

    def __init__(self, web_view, parent=None):
        super().__init__(parent)
        self.web_view = web_view
        self._syncing_scrollbars = False
        self._sync_pending = False
        self._pending_page_delta_x = 0.0
        self._pending_page_delta_y = 0.0
        self._page_wheel_flush_pending = False

        layout = QGridLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setHorizontalSpacing(3)
        layout.setVerticalSpacing(3)
        layout.addWidget(web_view, 0, 0)

        self.vertical_scrollbar = QScrollBar(Qt.Vertical)
        self.horizontal_scrollbar = QScrollBar(Qt.Horizontal)
        self.vertical_scrollbar.setObjectName("DeliverableVerticalScrollBar")
        self.horizontal_scrollbar.setObjectName("DeliverableHorizontalScrollBar")
        self.vertical_scrollbar.setVisible(False)
        self.horizontal_scrollbar.setVisible(False)
        layout.addWidget(self.vertical_scrollbar, 0, 1)
        layout.addWidget(self.horizontal_scrollbar, 1, 0)

        scrollbar_style = f"""
            QScrollBar {{ background: transparent; border: none; margin: 0px; }}
            QScrollBar:vertical {{ width: 10px; }}
            QScrollBar:horizontal {{ height: 10px; }}
            QScrollBar::handle {{ background: {DesignTokens.border_strong}; border-radius: 5px; min-width: 30px; min-height: 30px; }}
            QScrollBar::handle:hover {{ background: {DesignTokens.text_tertiary}; }}
            QScrollBar::add-line, QScrollBar::sub-line {{ width: 0px; height: 0px; }}
            QScrollBar::add-page, QScrollBar::sub-page {{ background: transparent; }}
        """
        self.vertical_scrollbar.setStyleSheet(scrollbar_style)
        self.horizontal_scrollbar.setStyleSheet(scrollbar_style)
        self.vertical_scrollbar.valueChanged.connect(self._apply_scrollbar_values)
        self.horizontal_scrollbar.valueChanged.connect(self._apply_scrollbar_values)
        web_view.loadFinished.connect(self._handle_load_finished)
        app = QApplication.instance()
        if app is None:
            raise RuntimeError("HTML 预览滚轮控制需要已初始化的 QApplication")
        app.installEventFilter(self)

    def _handle_load_finished(self, ok):
        if not ok:
            return
        self.schedule_scrollbar_sync()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.schedule_scrollbar_sync()

    def eventFilter(self, obj, event):
        if event.type() == QEvent.Wheel and not (event.modifiers() & Qt.ControlModifier):
            if not self.isVisible() or not self.web_view.isVisible():
                return super().eventFilter(obj, event)
            try:
                global_position = event.globalPosition().toPoint()
                position = self.web_view.mapFromGlobal(global_position)
            except Exception:
                return super().eventFilter(obj, event)
            if not self.web_view.rect().contains(position):
                return super().eventFilter(obj, event)
            pixel_delta = event.pixelDelta()
            angle_delta = event.angleDelta()
            delta_x = -pixel_delta.x() if not pixel_delta.isNull() else -angle_delta.x() / 2
            delta_y = -pixel_delta.y() if not pixel_delta.isNull() else -angle_delta.y() / 2
            if event.modifiers() & Qt.ShiftModifier and not delta_x:
                delta_x = delta_y
                delta_y = 0
            script = (
                "window.__coworkScrollWheelAt && "
                f"window.__coworkScrollWheelAt({position.x()},{position.y()},"
                f"{delta_x:.2f},{delta_y:.2f})"
            )
            self.web_view.page().runJavaScript(
                script,
                lambda result, x=delta_x, y=delta_y: self._handle_wheel_result(result, x, y),
            )
            event.accept()
            return True
        return super().eventFilter(obj, event)

    def _handle_wheel_result(self, result, delta_x, delta_y):
        if result == "page":
            self._pending_page_delta_x += delta_x
            self._pending_page_delta_y += delta_y
            if not self._page_wheel_flush_pending:
                self._page_wheel_flush_pending = True
                QTimer.singleShot(0, self._flush_page_wheel_delta)
            return
        if result == "nested":
            self.web_view.update()
        self.schedule_scrollbar_sync()

    def _flush_page_wheel_delta(self):
        self._page_wheel_flush_pending = False
        delta_x = self._pending_page_delta_x
        delta_y = self._pending_page_delta_y
        self._pending_page_delta_x = 0.0
        self._pending_page_delta_y = 0.0
        if delta_x:
            self.horizontal_scrollbar.setValue(
                self.horizontal_scrollbar.value() + int(round(delta_x))
            )
        if delta_y:
            self.vertical_scrollbar.setValue(
                self.vertical_scrollbar.value() + int(round(delta_y))
            )

    def schedule_scrollbar_sync(self):
        if self._sync_pending:
            return
        self._sync_pending = True
        QTimer.singleShot(0, self._sync_scrollbars)

    def _sync_scrollbars(self):
        self._sync_pending = False
        self.web_view.page().runJavaScript(
            "window.__coworkPreviewMetrics ? JSON.stringify(window.__coworkPreviewMetrics()) : ''",
            self._apply_page_metrics,
        )

    def _apply_page_metrics(self, metrics):
        if isinstance(metrics, str):
            try:
                metrics = json.loads(metrics)
            except json.JSONDecodeError:
                metrics = None
        if not isinstance(metrics, dict):
            return
        self._syncing_scrollbars = True
        try:
            width = max(0, int(metrics.get("width") or 0))
            height = max(0, int(metrics.get("height") or 0))
            client_width = max(0, int(metrics.get("clientWidth") or 0))
            client_height = max(0, int(metrics.get("clientHeight") or 0))
            max_x = max(0, width - client_width)
            max_y = max(0, height - client_height)
            self.horizontal_scrollbar.setRange(0, max_x)
            self.horizontal_scrollbar.setPageStep(client_width)
            self.horizontal_scrollbar.setValue(max(0, int(metrics.get("left") or 0)))
            self.horizontal_scrollbar.setVisible(max_x > 1)
            self.vertical_scrollbar.setRange(0, max_y)
            self.vertical_scrollbar.setPageStep(client_height)
            self.vertical_scrollbar.setValue(max(0, int(metrics.get("top") or 0)))
            self.vertical_scrollbar.setVisible(max_y > 1)
        finally:
            self._syncing_scrollbars = False

    def _apply_scrollbar_values(self, _value):
        if self._syncing_scrollbars:
            return
        x = self.horizontal_scrollbar.value()
        y = self.vertical_scrollbar.value()
        self.web_view.page().runJavaScript(
            f"window.scrollTo({x},{y})",
            lambda _result: self._handle_page_scroll_applied(),
        )

    def _handle_page_scroll_applied(self):
        self.web_view.update()
        self.schedule_scrollbar_sync()

class SmartSplitterHandle(QSplitterHandle):
    def __init__(self, orientation, parent):
        super().__init__(orientation, parent)

    def mouseDoubleClickEvent(self, event):
        # Reset to default sizes on double click
        if self.splitter():
            self.splitter().on_handle_double_clicked(self)

    def mouseReleaseEvent(self, event):
        super().mouseReleaseEvent(event)
        if self.splitter():
            self.splitter().check_auto_collapse()

class SmartSplitter(QSplitter):
    def __init__(self, orientation, parent=None):
        super().__init__(orientation, parent)
        self.setHandleWidth(1) # Visual width is 1px via CSS, but we keep this consistent
        
        # Default Stylesheet for Handles
        base_style = """
            QSplitter::handle { 
                background-color: #e5e7eb; 
                margin: 0 4px; 
            } 
            QSplitter::handle:hover { 
                background-color: #3b82f6; 
            }
        """
        if orientation == Qt.Horizontal:
            # Horizontal handles have vertical margin/padding in some contexts, but here margin 0 4px is for horizontal spacing?
            # Actually for horizontal splitter, handle is vertical bar.
            # margin: 0 4px means top/bottom 0, left/right 4px? No.
            # In Qt SS, margin is usually external.
            # Let's use the user provided CSS which was known good.
            self.setStyleSheet("""
                QSplitter::handle:horizontal { 
                    background-color: transparent; 
                    width: 1px; 
                    margin: 0; 
                } 
                QSplitter::handle:horizontal:hover { 
                    background-color: rgba(0, 122, 255, 0.16); 
                }
                QSplitter::handle:vertical { 
                    background-color: #d2d2d7; 
                    height: 1px; 
                    margin: 4px 0; 
                } 
                QSplitter::handle:vertical:hover { 
                    background-color: #007aff; 
                }
            """)
        else:
            self.setStyleSheet("""
                QSplitter::handle:vertical { 
                    background-color: #d2d2d7; 
                    height: 1px; 
                    margin: 4px 0; 
                } 
                QSplitter::handle:vertical:hover { 
                    background-color: #007aff; 
                }
            """)

    def createHandle(self):
        return SmartSplitterHandle(self.orientation(), self)

    def on_handle_double_clicked(self, handle):
        # Find which handle was clicked
        idx = -1
        for i in range(1, self.count()):
            if self.handle(i) == handle:
                idx = i
                break
        
        if idx == -1:
            return

        sizes = self.sizes()
        if self.orientation() == Qt.Horizontal:
            # Assuming 3-column layout: [Sidebar, Main, RightSidebar]
            # Handle 1: Between Sidebar (0) and Main (1)
            if idx == 1: 
                target_width = 260
                if len(sizes) > 1:
                    current_w = sizes[0]
                    diff = target_width - current_w
                    sizes[0] = target_width
                    sizes[1] -= diff
            # Handle 2: Between Main (1) and RightSidebar (2)
            elif idx == 2:
                target_width = 280
                if len(sizes) > 2:
                    current_w = sizes[2]
                    diff = target_width - current_w
                    sizes[2] = target_width
                    sizes[1] -= diff
        else:
            # Vertical Splitter (Workspace)
            # Default ratio 2:1
            total = sum(sizes)
            target_h1 = int(total * 0.66)
            target_h2 = total - target_h1
            sizes = [target_h1, target_h2]
            
        self.setSizes(sizes)

    def check_auto_collapse(self):
        if self.orientation() == Qt.Horizontal:
            sizes = self.sizes()
            # Left sidebar (index 0)
            if len(sizes) > 0 and sizes[0] < 50 and sizes[0] > 0:
                sizes[1] += sizes[0]
                sizes[0] = 0
                self.setSizes(sizes)
            
            # Right sidebar (index 2)
            if len(sizes) > 2:
                if sizes[2] < 50 and sizes[2] > 0:
                    sizes[1] += sizes[2]
                    sizes[2] = 0
                    self.setSizes(sizes)


class MemoryUpdateWorker(QThread):
    progress_signal = Signal(str)
    batch_preview_signal = Signal(dict)
    finished_signal = Signal(dict)

    def __init__(self, config_manager, chat_storage, history_dir, scope="global", workspace_dir="", parent=None):
        super().__init__(parent)
        self.config_manager = config_manager
        self.chat_storage = chat_storage
        self.history_dir = history_dir
        self.scope = scope
        self.workspace_dir = workspace_dir or ""

    def run(self):
        try:
            cutoff_at = int(time.time())
            update_state = memory_update_scope_state(self.history_dir, self.scope, self.workspace_dir)
            last_processed_at = int(update_state.get("last_processed_at") or 0)
            transcripts = self.chat_storage.iter_conversation_transcripts(
                include_archived=True,
                include_legacy_json=True,
            )
            transcripts = [
                item for item in transcripts
                if item.get("messages")
            ]
            if self.scope == "workspace":
                transcripts = filter_transcripts_for_workspace(transcripts, self.workspace_dir)
            all_transcript_count = len(transcripts)
            transcripts = filter_transcripts_for_memory_update(
                transcripts,
                last_processed_at=last_processed_at,
                cutoff_at=cutoff_at,
            )
            if not transcripts:
                self.finished_signal.emit({
                    "ok": False,
                    "empty": True,
                    "error": "当前工作区没有新增或变更的历史会话。" if self.scope == "workspace" else "没有上次更新后新增或变更的历史会话。",
                    "last_processed_at": last_processed_at,
                    "cutoff_at": cutoff_at,
                    "all_transcript_count": all_transcript_count,
                })
                return

            self.progress_signal.emit(
                f"发现 {len(transcripts)} 个需要更新的历史会话；已跳过 {max(0, all_transcript_count - len(transcripts))} 个旧会话"
            )
            self.progress_signal.emit("正在读取当前工作区摘要" if self.scope == "workspace" else "正在读取全局长期摘要")
            current_memory = MemoryStore(self.history_dir).read_summary(self.scope, self.workspace_dir)
            self.progress_signal.emit("正在连接当前模型")
            provider = LLMFactory.create_provider(self.config_manager)
            result = generate_memory_update(
                provider,
                current_memory,
                transcripts,
                max_batch_tokens=DEFAULT_MEMORY_BATCH_TOKEN_LIMIT,
                progress_callback=self.progress_signal.emit,
            )
            result.update({
                "ok": True,
                "current_memory": current_memory,
                "cutoff_at": cutoff_at,
                "last_processed_at": last_processed_at,
                "processed_transcripts": transcripts,
                "all_transcript_count": all_transcript_count,
                "scope": self.scope,
                "workspace_dir": self.workspace_dir,
            })
            self.finished_signal.emit(result)
        except Exception as exc:
            self.finished_signal.emit({
                "ok": False,
                "error": str(exc),
            })


class MemoryCenterDialog(QDialog):
    def __init__(self, history_dir, workspace_dir="", parent=None):
        super().__init__(parent)
        self.setWindowTitle("记忆")
        self.resize(980, 700)
        self.setMinimumSize(820, 560)
        self.store = MemoryStore(history_dir)
        self.workspace_dir = workspace_dir or ""
        self.setStyleSheet(f"QDialog {{ background: {DesignTokens.bg_app}; }}")

        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 22, 24, 22)
        layout.setSpacing(14)
        title = QLabel("记忆")
        title.setStyleSheet(apple_section_title_style(22))
        subtitle = QLabel("管理全局与当前工作区的长期摘要，以及所有智能体共享的性格底色。")
        subtitle.setStyleSheet(apple_caption_style())
        layout.addWidget(title)
        layout.addWidget(subtitle)

        self.tabs = QTabWidget()
        self.tabs.setDocumentMode(True)
        layout.addWidget(self.tabs, 1)

        summary_page = QWidget()
        summary_layout = QVBoxLayout(summary_page)
        summary_layout.setContentsMargins(12, 16, 12, 12)
        summary_bar = QHBoxLayout()
        self.summary_scope = QComboBox()
        self.summary_scope.addItem("全局摘要", "global")
        if self.workspace_dir:
            self.summary_scope.addItem("当前工作区摘要", "workspace")
        self.summary_scope.currentIndexChanged.connect(self.handle_summary_scope_changed)
        summary_bar.addWidget(self.summary_scope)
        summary_bar.addStretch()
        self.generate_btn = QPushButton("从历史生成")
        self.generate_btn.setObjectName("SecondaryBtn")
        self.generate_btn.clicked.connect(self.start_generation)
        summary_bar.addWidget(self.generate_btn)
        summary_layout.addLayout(summary_bar)
        self.summary_edit = QTextEdit()
        self.summary_edit.setPlaceholderText("记录需要始终提供给 AI 的精简、稳定信息。")
        self.summary_edit.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=16, subtle=True, padding=12))
        summary_layout.addWidget(self.summary_edit, 1)
        summary_save = QPushButton("保存摘要")
        summary_save.setObjectName("PrimaryBtn")
        summary_save.clicked.connect(self.save_summary)
        summary_layout.addWidget(summary_save, 0, Qt.AlignRight)
        self.tabs.addTab(summary_page, "长期摘要")

        soul_page = QWidget()
        soul_layout = QVBoxLayout(soul_page)
        soul_layout.setContentsMargins(12, 16, 12, 12)
        soul_hint = QLabel("描述 AI 是怎样的性格、如何与你相处以及表达偏好。具体智能体角色会叠加在这层性格之上。")
        soul_hint.setWordWrap(True)
        soul_hint.setStyleSheet(apple_caption_style())
        soul_layout.addWidget(soul_hint)
        self.soul_edit = QTextEdit()
        self.soul_edit.setPlaceholderText("例如：你温和、好奇、坦率，喜欢先理解问题，再给出清晰而有主见的建议。")
        self.soul_edit.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=16, subtle=True, padding=12))
        soul_layout.addWidget(self.soul_edit, 1)
        soul_save = QPushButton("保存灵魂提示词")
        soul_save.setObjectName("PrimaryBtn")
        soul_save.clicked.connect(self.save_soul)
        soul_layout.addWidget(soul_save, 0, Qt.AlignRight)
        self.tabs.addTab(soul_page, "灵魂提示词")

        close_btn = QPushButton("完成")
        close_btn.setObjectName("SecondaryBtn")
        close_btn.clicked.connect(self.accept)
        layout.addWidget(close_btn, 0, Qt.AlignRight)
        self.load_summary()
        self.soul_edit.setPlainText(self.store.read_soul())

    def _scope(self):
        return self.summary_scope.currentData() or "global"

    def load_summary(self):
        scope = self._scope()
        self.summary_edit.setPlainText(self.store.read_summary(scope, self.workspace_dir))

    def handle_summary_scope_changed(self):
        self.generate_btn.setText("从当前工作区生成" if self._scope() == "workspace" else "从历史生成")
        self.load_summary()

    def save_summary(self):
        try:
            self.store.save_summary(self.summary_edit.toPlainText(), self._scope(), self.workspace_dir)
            QMessageBox.information(self, "记忆", "长期摘要已保存，将从下一轮对话开始生效。")
        except Exception as exc:
            QMessageBox.critical(self, "保存失败", str(exc))

    def save_soul(self):
        try:
            self.store.save_soul(self.soul_edit.toPlainText())
            QMessageBox.information(self, "记忆", "灵魂提示词已保存，将从下一轮对话开始生效。")
        except Exception as exc:
            QMessageBox.critical(self, "保存失败", str(exc))

    def start_generation(self):
        self.hide()
        if self.parent() and hasattr(self.parent(), "start_memory_update"):
            self.parent().start_memory_update(self._scope(), self.workspace_dir)


class MemoryUpdateDialog(QDialog):
    save_requested = Signal(str)
    background_requested = Signal()

    def __init__(self, scope_label="全部历史", parent=None):
        super().__init__(parent)
        self.setWindowTitle("生成长期记忆")
        self.resize(760, 620)
        self.running = True
        self.setStyleSheet(f"QDialog {{ background: {DesignTokens.bg_app}; }}")

        layout = QVBoxLayout(self)
        layout.setContentsMargins(18, 18, 18, 18)
        layout.setSpacing(12)

        title = QLabel(f"正在根据{scope_label}生成长期摘要")
        title.setStyleSheet(f"font-size: 16px; font-weight: 700; color: {DesignTokens.text_primary};")
        layout.addWidget(title)

        self.status_label = QLabel("准备开始")
        self.status_label.setWordWrap(True)
        self.status_label.setStyleSheet(f"color: {DesignTokens.text_secondary}; font-size: 12px;")
        layout.addWidget(self.status_label)

        process_label = QLabel("更新过程")
        process_label.setStyleSheet(f"font-size: 12px; font-weight: 700; color: {DesignTokens.text_primary};")
        layout.addWidget(process_label)

        self.process_log = QTextEdit()
        self.process_log.setReadOnly(True)
        self.process_log.setFixedHeight(150)
        self.process_log.setStyleSheet(
            f"border: 1px solid {DesignTokens.border}; border-radius: 8px; "
            f"background: {DesignTokens.bg_secondary}; color: {DesignTokens.text_primary}; "
            "font-family: 'Consolas', monospace; font-size: 12px; padding: 8px;"
        )
        layout.addWidget(self.process_log)

        result_label = QLabel("更新结果")
        result_label.setStyleSheet(f"font-size: 12px; font-weight: 700; color: {DesignTokens.text_primary};")
        layout.addWidget(result_label)

        self.editor = QTextEdit()
        self.editor.setReadOnly(True)
        self.editor.setPlaceholderText("生成完成后会在这里显示待确认的长期记忆草稿。")
        self.editor.setStyleSheet(
            f"border: 1px solid {DesignTokens.border}; border-radius: 8px; "
            f"background: {DesignTokens.bg_card}; color: {DesignTokens.text_primary}; "
            "font-family: 'Consolas', monospace; font-size: 12px; padding: 10px;"
        )
        layout.addWidget(self.editor, 1)

        button_row = QHBoxLayout()
        button_row.addStretch()
        self.background_btn = QPushButton("缩小到后台")
        self.background_btn.setCursor(Qt.PointingHandCursor)
        self.background_btn.clicked.connect(self.hide_to_background)
        self.close_btn = QPushButton("关闭")
        self.close_btn.setCursor(Qt.PointingHandCursor)
        self.close_btn.setEnabled(False)
        self.close_btn.clicked.connect(self.reject)
        self.save_btn = QPushButton("确认并保存摘要")
        self.save_btn.setCursor(Qt.PointingHandCursor)
        self.save_btn.setEnabled(False)
        self.save_btn.setIcon(qta.icon('fa5s.save', color='#ffffff'))
        self.save_btn.setStyleSheet(
            f"background-color: {DesignTokens.primary}; color: white; border-radius: 12px; "
            "padding: 8px 14px; font-weight: 700; border: none;"
        )
        self.save_btn.clicked.connect(lambda: self.save_requested.emit(self.memory_text()))
        button_row.addWidget(self.background_btn)
        button_row.addWidget(self.close_btn)
        button_row.addWidget(self.save_btn)
        layout.addLayout(button_row)

    def append_progress(self, text):
        text = str(text or "").strip()
        if not text:
            return
        self.status_label.setText(text)
        timestamp = datetime.now().strftime("%H:%M:%S")
        self.process_log.append(f"[{timestamp}] {text}")

    def show_result(self, memory_text, stats):
        self.running = False
        self.append_progress("长期记忆预览生成完成")
        self.status_label.setText(stats)
        self.editor.setReadOnly(False)
        self.editor.setPlainText(memory_text or "")
        self.save_btn.setEnabled(True)
        self.close_btn.setEnabled(True)
        self.background_btn.setEnabled(False)

    def show_batch_result(self, memory_text, stats):
        self.status_label.setText(stats)
        self.editor.setReadOnly(True)
        self.editor.setPlainText(memory_text or "")
        self.append_progress(stats)

    def show_error(self, message):
        self.running = False
        self.status_label.setText(message)
        self.append_progress(message)
        self.close_btn.setEnabled(True)
        self.save_btn.setEnabled(False)
        self.background_btn.setEnabled(False)

    def mark_saved(self, message):
        self.running = False
        self.status_label.setText(message)
        self.append_progress(message)
        self.save_btn.setEnabled(False)
        self.close_btn.setEnabled(True)
        self.background_btn.setEnabled(False)

    def memory_text(self):
        return self.editor.toPlainText()

    def hide_to_background(self):
        self.hide()
        self.background_requested.emit()

    def closeEvent(self, event):
        if self.running:
            self.hide_to_background()
            event.ignore()
            return
        super().closeEvent(event)


class ConversationSkillDraftWorker(QThread):
    progress_signal = Signal(str)
    finished_signal = Signal(dict)

    def __init__(
        self,
        config_manager,
        session_id,
        title,
        messages,
        meta=None,
        mode="create",
        target_skill=None,
        update_strategy="append",
        parent=None,
    ):
        super().__init__(parent)
        self.config_manager = config_manager
        self.session_id = session_id
        self.title = title
        self.messages = list(messages or [])
        self.meta = dict(meta or {})
        self.mode = mode
        self.target_skill = target_skill
        self.update_strategy = update_strategy

    def run(self):
        try:
            if not self.messages:
                self.finished_signal.emit({
                    "ok": False,
                    "error": "当前会话没有可沉淀的消息。",
                })
                return
            self.progress_signal.emit("正在整理当前会话记录")
            transcript = render_session_transcript(
                self.session_id,
                self.title,
                self.messages,
                meta=self.meta,
            )
            self.progress_signal.emit("正在让模型提炼 Skill 草稿")
            provider = LLMFactory.create_provider(self.config_manager)
            draft = generate_skill_draft(
                provider,
                transcript,
                mode=self.mode,
                target_skill=self.target_skill,
                update_strategy=self.update_strategy,
                fallback_title=self.title,
            )
            draft["script_assets"] = extract_python_script_assets(self.messages)
            self.finished_signal.emit({
                "ok": True,
                "draft": draft,
                "mode": self.mode,
                "target_skill": self.target_skill,
                "update_strategy": self.update_strategy,
            })
        except Exception as exc:
            self.finished_signal.emit({
                "ok": False,
                "error": str(exc),
            })


class ConversationSopDraftWorker(QThread):
    progress_signal = Signal(str)
    finished_signal = Signal(dict)

    def __init__(
        self,
        config_manager,
        session_id,
        title,
        messages,
        meta=None,
        previous_draft=None,
        revision_feedback="",
        parent=None,
    ):
        super().__init__(parent)
        self.config_manager = config_manager
        self.session_id = session_id
        self.title = title
        self.messages = list(messages or [])
        self.meta = dict(meta or {})
        self.previous_draft = dict(previous_draft or {})
        self.revision_feedback = str(revision_feedback or "")

    def run(self):
        try:
            if not self.messages:
                self.finished_signal.emit({
                    "ok": False,
                    "session_id": self.session_id,
                    "error": "当前会话没有可提炼 SOP 的消息。",
                })
                return
            self.progress_signal.emit("正在整理当前会话记录")
            transcript = render_session_transcript(
                self.session_id,
                self.title,
                self.messages,
                meta=self.meta,
            )
            self.progress_signal.emit("正在让模型提炼 SOP 草稿")
            provider = LLMFactory.create_provider(self.config_manager)
            draft = generate_sop_draft(
                provider,
                transcript,
                fallback_title=self.title,
                previous_draft=self.previous_draft,
                revision_feedback=self.revision_feedback,
            )
            self.finished_signal.emit({
                "ok": True,
                "session_id": self.session_id,
                "draft": draft,
            })
        except Exception as exc:
            self.finished_signal.emit({
                "ok": False,
                "session_id": self.session_id,
                "error": str(exc),
            })


class SopStepExecutorWorker(QThread):
    finished_signal = Signal(dict, str)

    def __init__(self, session_id, sop_run, workspace_dir, parent=None):
        super().__init__(parent)
        self.session_id = str(session_id or "")
        self.sop_run = json.loads(json.dumps(sop_run or {}, ensure_ascii=False))
        self.workspace_dir = workspace_dir

    def run(self):
        result = execute_sop_step(self.sop_run, self.workspace_dir)
        self.finished_signal.emit(result, self.session_id)


