    def process_ui_events(self, force=False):
        import time
        now = time.time()
        if force or (now - self.last_ui_update_time > 0.05):
            QApplication.processEvents()
            self.last_ui_update_time = now

    def showEvent(self, event):
        super().showEvent(event)
        if not self._startup_hydration_scheduled:
            self._startup_hydration_scheduled = True
            QTimer.singleShot(0, self._run_startup_hydration)
        if not self._background_services_scheduled:
            self._background_services_scheduled = True
            QTimer.singleShot(0, self.start_background_services)

    def _run_startup_hydration(self):
        if self._startup_hydration_completed:
            return
        self._startup_hydration_completed = True
        log_startup_stage("startup_hydration_begin")
        self.load_default_workspace(refresh_sidebar=False)
        log_startup_stage("startup_workspace_ready", has_workspace=bool(self.workspace_dir))
        self.refresh_history_list()
        log_startup_stage("startup_history_ready")

    def keyPressEvent(self, event):
        if event.key() == Qt.Key_Escape and getattr(self, "right_drawer_open", False):
            self.hide_context_drawer()
            event.accept()
            return
        super().keyPressEvent(event)

    def set_context_drawer_width(self, requested_width):
        parent = getattr(self, "main_container", None)
        if not parent:
            return
        maximum = max(self.context_drawer_min_width, int(parent.width() * 0.72))
        self.context_drawer_user_width = self._clamp_int(
            int(requested_width), self.context_drawer_min_width, maximum
        )
        self.context_drawer_expanded = self.context_drawer_user_width > self.context_drawer_max_width
        self._sync_deliverable_expand_button()
        self.sync_context_drawer_layout()

    def persist_context_drawer_width(self):
        if getattr(self, "config_manager", None) and self.context_drawer_user_width:
            self.config_manager.set("context_drawer_width", int(self.context_drawer_user_width))

    def persist_deliverables_splitter_sizes(self, *_args):
        splitter = getattr(self, "deliverables_splitter", None)
        if not splitter or not getattr(self, "config_manager", None):
            return
        sizes = [int(value) for value in splitter.sizes()]
        if len(sizes) == 2 and all(value > 0 for value in sizes):
            self.config_manager.set("deliverables_splitter_sizes", sizes)

    def set_file_workspace_section(self, section, refresh=True):
        section = section if section == getattr(self, "FILE_SECTION_DELIVERABLES", "deliverables") else getattr(self, "FILE_SECTION_ALL", "all")
        self.file_workspace_section = section
        stack = getattr(self, "file_source_stack", None)
        if stack is not None:
            stack.setCurrentIndex(1 if section == self.FILE_SECTION_DELIVERABLES else 0)
            stack.setVisible(section != self.FILE_SECTION_DELIVERABLES or getattr(self, "deliverable_layout_mode", "list") == "list")
        for key, btn in getattr(self, "file_section_buttons", {}).items():
            btn.setChecked(key == section)
        deliverable_controls_visible = section == self.FILE_SECTION_DELIVERABLES
        for name in ("deliverable_layout_btn", "deliverable_render_btn", "deliverable_expand_btn", "deliverables_refresh_btn"):
            btn = getattr(self, name, None)
            if btn is not None:
                btn.setVisible(deliverable_controls_visible)
        self._sync_deliverable_action_visibility()
        if deliverable_controls_visible and refresh:
            self.refresh_deliverables(render_current=True)
        self.update_context_drawer_header(getattr(self, "right_drawer_tab", self.RIGHT_TAB_FILES))

    def _sync_deliverable_action_visibility(self):
        section = getattr(self, "file_workspace_section", getattr(self, "FILE_SECTION_ALL", "all"))
        in_deliverables = section == getattr(self, "FILE_SECTION_DELIVERABLES", "deliverables")
        path = getattr(self, "current_deliverable_path", "") if in_deliverables else ""
        ext = os.path.splitext(path)[1].lower() if path else ""
        is_html = ext in {".html", ".htm"} and os.path.isfile(path)
        row = getattr(self, "deliverable_conversion_row", None)
        if row is not None:
            row.setVisible(in_deliverables and is_html)
        status = getattr(self, "deliverable_status_label", None)
        if status is not None:
            status.setVisible(True)

    def _apply_deliverable_layout_mode(self, mode, persist=True):
        mode = "focus" if mode == "focus" else "list"
        self.deliverable_layout_mode = mode
        source_stack = getattr(self, "file_source_stack", None)
        if source_stack is not None:
            in_deliverables = getattr(self, "file_workspace_section", "") == getattr(self, "FILE_SECTION_DELIVERABLES", "deliverables")
            source_stack.setVisible(mode == "list" or not in_deliverables)
        btn = getattr(self, "deliverable_layout_btn", None)
        if btn is not None:
            if mode == "focus":
                btn.setIcon(qta.icon("fa5s.list", color=DesignTokens.text_secondary))
                btn.setToolTip("显示交付物列表")
            else:
                btn.setIcon(qta.icon("fa5s.file-alt", color=DesignTokens.text_secondary))
                btn.setToolTip("专注预览")
        if persist:
            self.config_manager.set("deliverable_layout_mode", mode)
        meta = getattr(self, "preview_meta_label", None)
        if meta is not None:
            if mode == "focus" and getattr(self, "current_deliverable_path", ""):
                try:
                    meta.setText(os.path.relpath(self.current_deliverable_path, self.workspace_dir))
                except ValueError:
                    meta.setText(self.current_deliverable_path)
            elif mode == "list":
                meta.setText(f"最近 {len(getattr(self, 'deliverable_items', []) or [])} 个产物 · 选择文件预览")
        self._sync_deliverable_action_visibility()

    def toggle_deliverable_layout_mode(self):
        target = "list" if getattr(self, "deliverable_layout_mode", "list") == "focus" else "focus"
        self._apply_deliverable_layout_mode(target)

    def _sync_deliverable_expand_button(self):
        btn = getattr(self, "deliverable_expand_btn", None)
        if not btn:
            return
        expanded = bool(getattr(self, "context_drawer_expanded", False))
        btn.setIcon(qta.icon("fa5s.compress-alt" if expanded else "fa5s.expand-alt", color=DesignTokens.text_secondary))
        btn.setToolTip("退出放大" if expanded else "放大预览")

    def toggle_deliverable_preview_expanded(self):
        parent = getattr(self, "main_container", None)
        if not parent:
            return
        if getattr(self, "context_drawer_expanded", False):
            self.context_drawer_expanded = False
            self.context_drawer_user_width = (
                self.context_drawer_width_before_expand
                or min(DesignTokens.drawer_max_width, max(DesignTokens.drawer_preferred_min_width, int(parent.width() * DesignTokens.drawer_width_ratio)))
            )
        else:
            self.context_drawer_width_before_expand = self.right_sidebar.width() if hasattr(self, "right_sidebar") else 0
            self.context_drawer_expanded = True
            self.context_drawer_user_width = max(
                DesignTokens.drawer_max_width + 1,
                min(int(parent.width() * 0.68), parent.width() - (self.context_drawer_margin * 2)),
            )
        self._sync_deliverable_expand_button()
        self.persist_context_drawer_width()
        self.sync_context_drawer_layout()

    def _compute_context_drawer_geometry(self):
        if not hasattr(self, "right_sidebar"):
            return None
        parent = self.right_sidebar.parentWidget()
        if not parent:
            return None
        margin = self.context_drawer_margin
        content_width = parent.width() - self.main_layout_default_margins[0] - self.main_layout_default_margins[2]
        default_width = self._clamp_int(
            int(content_width * DesignTokens.drawer_width_ratio),
            self.context_drawer_preferred_min_width,
            self.context_drawer_max_width,
        )
        width = int(getattr(self, "context_drawer_user_width", 0) or default_width)
        width_limit = content_width - self.context_drawer_gap - self.context_drawer_min_content_width
        if getattr(self, "context_drawer_expanded", False):
            width = min(width, max(self.context_drawer_min_width, int(parent.width() * 0.72)))
        elif width_limit < self.context_drawer_preferred_min_width:
            width = max(self.context_drawer_min_width, width_limit)
        else:
            width = min(width, width_limit)
        width = min(width, max(self.context_drawer_min_width, parent.width() - (margin * 2)))
        height = max(120, parent.height() - (margin * 2))
        x = parent.width() - width - margin
        return {
            "margin": margin,
            "width": width,
            "height": height,
            "x": x,
            "y": margin,
        }

    def _apply_context_drawer_content_reserve(self, drawer_width=None):
        if not hasattr(self, "main_content_layout"):
            return
        left, top, right, bottom = self.main_content_default_margins
        reserve = 0
        if getattr(self, "right_drawer_open", False) and drawer_width:
            reserve = max(0, int(drawer_width) + int(self.context_drawer_gap))
        self.content_area_layout.setContentsMargins(left, top, reserve, bottom)
        self.main_content_layout.setContentsMargins(0, 0, 0, 0)

    def _clamp_int(self, value, minimum, maximum):
        minimum = int(minimum)
        maximum = int(maximum)
        if maximum < minimum:
            return maximum
        return max(minimum, min(maximum, int(value)))

    def _drawer_is_active(self, drawer_geometry=None):
        return bool(self.right_drawer_open and isinstance(drawer_geometry, dict))

    def _main_content_shell_width(self, drawer_geometry=None):
        container = getattr(self, "main_container", None)
        if container is None:
            return DesignTokens.conversation_min_width
        available = container.width() - self.main_layout_default_margins[0] - self.main_layout_default_margins[2]
        if self._drawer_is_active(drawer_geometry):
            safe_right = int(drawer_geometry.get("x", container.width())) - self.context_drawer_gap
            available = min(
                available,
                safe_right - self.main_layout_default_margins[0],
            )
        return max(available, 0)

    def _conversation_available_width(self, drawer_geometry=None):
        return max(self._main_content_shell_width(drawer_geometry), 0)

    def _compute_conversation_shell_metrics(self, drawer_geometry=None):
        shell_width = self._main_content_shell_width(drawer_geometry)
        drawer_open = self._drawer_is_active(drawer_geometry)
        compact_min = (
            DesignTokens.conversation_open_compact_min_width
            if drawer_open else
            DesignTokens.conversation_compact_min_width
        )
        max_conversation_width = min(DesignTokens.conversation_max_width, shell_width)
        min_conversation_width = min(
            DesignTokens.conversation_min_width if not drawer_open else DesignTokens.conversation_open_min_width,
            max_conversation_width,
        )
        compact_conversation_width = min(compact_min, max_conversation_width)
        if drawer_open:
            conversation_width = self._clamp_int(
                int(shell_width * DesignTokens.conversation_open_target_ratio),
                compact_conversation_width,
                min(DesignTokens.conversation_open_max_width, shell_width),
            )
        else:
            conversation_width = self._clamp_int(
                int(shell_width * DesignTokens.conversation_closed_target_ratio),
                min(DesignTokens.conversation_closed_min_width, max_conversation_width),
                min(DesignTokens.conversation_closed_max_width, shell_width),
            )
        conversation_width = min(conversation_width, max_conversation_width)
        if not drawer_open and shell_width >= DesignTokens.conversation_min_width:
            conversation_width = max(conversation_width, min_conversation_width)
        else:
            conversation_width = max(conversation_width, compact_conversation_width)
        remaining = max(0, shell_width - conversation_width)
        if drawer_open:
            left_spacer_width = int(round(remaining * DesignTokens.conversation_open_left_spacer_ratio))
            right_spacer_width = remaining - left_spacer_width
        else:
            left_spacer_width = remaining // 2
            right_spacer_width = remaining - left_spacer_width
        return {
            "drawer_open": drawer_open,
            "shell_width": shell_width,
            "conversation_width": conversation_width,
            "left_spacer_width": left_spacer_width,
            "right_spacer_width": right_spacer_width,
            "drawer_width": int((drawer_geometry or {}).get("width", 0) or 0),
        }

    def _apply_conversation_shell_metrics(self, metrics):
        if not isinstance(metrics, dict):
            return
        left_spacer = getattr(self, "conversation_left_spacer", None)
        if left_spacer is not None:
            left_spacer.setFixedWidth(max(0, int(metrics.get("left_spacer_width", 0) or 0)))
        right_spacer = getattr(self, "conversation_right_spacer", None)
        if right_spacer is not None:
            right_spacer.setFixedWidth(max(0, int(metrics.get("right_spacer_width", 0) or 0)))

    def _iter_session_chat_bubbles(self):
        for state in getattr(self, "sessions", {}).values():
            chat_layout = getattr(state, "chat_layout", None)
            if chat_layout is None:
                continue
            for index in range(chat_layout.count()):
                item = chat_layout.itemAt(index)
                widget = item.widget() if item is not None else None
                if isinstance(widget, ChatBubble):
                    yield widget

    def _iter_session_sop_confirmation_bars(self):
        for state in getattr(self, "sessions", {}).values():
            bar = getattr(state, "sop_confirmation_bar", None)
            if bar is not None and _qt_object_alive(bar):
                yield bar

    def sync_conversation_widths(self, drawer_geometry=None):
        metrics = self._compute_conversation_shell_metrics(drawer_geometry)
        conversation_width = int(metrics.get("conversation_width", DesignTokens.conversation_min_width) or DesignTokens.conversation_min_width)
        message_width = self._clamp_int(
            int(conversation_width * DesignTokens.message_width_ratio),
            min(DesignTokens.message_compact_min_width, conversation_width),
            min(DesignTokens.message_max_width, conversation_width),
        )
        user_bubble_width = self._clamp_int(
            int(message_width * DesignTokens.user_bubble_ratio),
            min(DesignTokens.user_bubble_compact_min_width, message_width),
            min(DesignTokens.user_bubble_max_width, message_width),
        )

        self.dynamic_layout_metrics = metrics
        self.dynamic_conversation_width = conversation_width
        self.dynamic_message_width = message_width
        self.dynamic_user_bubble_width = user_bubble_width

        self._apply_conversation_shell_metrics(metrics)
        self.conversation_column.setFixedWidth(conversation_width)
        self.session_tabs.setFixedWidth(conversation_width)
        self.input_card.setFixedWidth(conversation_width)

        for bubble in self._iter_session_chat_bubbles():
            bubble.apply_dynamic_widths(message_width, user_bubble_width)
        for bar in self._iter_session_sop_confirmation_bars():
            bar.apply_dynamic_width(message_width)
        self._position_active_system_toast()

    def sync_context_drawer_layout(self):
        geometry = self._compute_context_drawer_geometry()
        if geometry is None:
            return
        self._apply_context_drawer_content_reserve(geometry["width"])
        self.sync_conversation_widths(geometry)
        self.right_sidebar.setGeometry(
            geometry["x"],
            geometry["y"],
            geometry["width"],
            geometry["height"],
        )
        if hasattr(self, "right_resize_handle"):
            self.right_resize_handle.setGeometry(0, 18, 8, max(40, geometry["height"] - 36))
            self.right_resize_handle.raise_()
        if self.right_sidebar.isVisible():
            self.right_sidebar.raise_()

    def _on_context_surface_changed(self, *_args):
        required = ("right_sidebar", "conversation_column", "session_tabs", "input_card")
        if any(not hasattr(self, name) for name in required):
            return
        self.sync_context_drawer_layout()

    def position_context_drawer(self):
        self.sync_context_drawer_layout()

    def show_context_drawer(self, tab_index=None):
        if tab_index is None:
            tab_index = self.right_drawer_tab
        if not hasattr(self, "right_stack"):
            return
        tab_index = max(0, min(tab_index, self.right_stack.count() - 1))
        log_sub_agent_runtime(
            "ui_context_drawer_show_begin",
            tab_index=tab_index,
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
            current_tab=getattr(self, "right_drawer_tab", None),
            drawer_open=bool(getattr(self, "right_drawer_open", False)),
        )
        try:
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="set_flags", tab_index=tab_index)
            self.right_drawer_tab = tab_index
            self.right_drawer_open = True
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="set_flags", tab_index=tab_index)

            if tab_index == self.RIGHT_TAB_OBSERVABILITY:
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="refresh_observability", tab_index=tab_index)
                self.refresh_observability_view(self.current_session_id)
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="refresh_observability", tab_index=tab_index)
            elif tab_index == self.RIGHT_TAB_DELIVERABLES:
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="refresh_deliverables", tab_index=tab_index)
                self.refresh_deliverables(render_current=True)
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="refresh_deliverables", tab_index=tab_index)
            elif tab_index == self.RIGHT_TAB_SUB_AGENTS and hasattr(self, "sub_agent_monitor") and _qt_object_alive(self.sub_agent_monitor):
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="clear_sub_agent_monitor", tab_index=tab_index)
                self.sub_agent_monitor.reset()
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="clear_sub_agent_monitor", tab_index=tab_index)

            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="set_current_index", tab_index=tab_index)
            self.right_stack.setCurrentIndex(tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="set_current_index", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="update_header", tab_index=tab_index)
            self.update_context_drawer_header(tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="update_header", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="set_visible", tab_index=tab_index)
            self.right_sidebar.setVisible(True)
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="set_visible", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="sync_layout", tab_index=tab_index)
            self.sync_context_drawer_layout()
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="sync_layout", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="raise_sidebar", tab_index=tab_index)
            self.right_sidebar.raise_()
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="raise_sidebar", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="update_badges", tab_index=tab_index)
            self.update_context_rail_badges()
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="update_badges", tab_index=tab_index)
            if tab_index == self.RIGHT_TAB_SUB_AGENTS:
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="queue_sub_agent_render", tab_index=tab_index)
                self._queue_render_sub_agent_monitor_for_state(self.get_current_session(), delay_ms=250)
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="queue_sub_agent_render", tab_index=tab_index)
            log_sub_agent_runtime(
                "ui_context_drawer_show_done",
                tab_index=tab_index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
                drawer_open=bool(getattr(self, "right_drawer_open", False)),
                drawer_tab=getattr(self, "right_drawer_tab", None),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_context_drawer_show_failed",
                tab_index=tab_index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
                traceback=traceback.format_exc(),
            )

    def update_context_drawer_header(self, tab_index):
        if not hasattr(self, "right_title_label") or not hasattr(self, "right_desc_label"):
            return
        page_titles = {
            self.RIGHT_TAB_FILES: ("文件与交付物", "查看工作区文件、预览交付物并继续生成"),
            self.RIGHT_TAB_OBSERVABILITY: ("任务观测", "查看系统提示词、工具调用与返回"),
            self.RIGHT_TAB_SUB_AGENTS: ("子 Agent", "查看并行子 Agent 状态与日志"),
        }
        title, description = page_titles.get(tab_index, ("任务上下文", "查看文件与执行步骤"))
        self.right_title_label.setText(title)
        self.right_desc_label.setText(description)

    def hide_context_drawer(self, reason="manual", source_obj=None, source_window=None, in_drawer=None, in_rail=None, is_popup=None):
        if not hasattr(self, "right_sidebar"):
            return
        log_sub_agent_runtime(
            "ui_context_drawer_hide_begin",
            reason=str(reason or "manual"),
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
            drawer_open=bool(getattr(self, "right_drawer_open", False)),
            drawer_tab=getattr(self, "right_drawer_tab", None),
            source_class=type(source_obj).__name__ if source_obj is not None else "",
            source_window_class=type(source_window).__name__ if source_window is not None else "",
            in_drawer=in_drawer,
            in_rail=in_rail,
            is_popup=is_popup,
        )
        self.right_drawer_open = False
        self.right_sidebar.setVisible(False)
        self.sync_context_drawer_layout()
        self.update_context_rail_badges()
        log_sub_agent_runtime(
            "ui_context_drawer_hide_done",
            reason=str(reason or "manual"),
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
            drawer_open=bool(getattr(self, "right_drawer_open", False)),
            drawer_tab=getattr(self, "right_drawer_tab", None),
        )

    def set_context_tab_hint(self, tab_index, available=True):
        if not hasattr(self, "context_available_tabs"):
            return
        if available:
            self.context_available_tabs.add(tab_index)
        else:
            self.context_available_tabs.discard(tab_index)
        self.update_context_rail_badges()

    def update_context_rail_badges(self):
        if not hasattr(self, "context_rail_buttons"):
            return
        icons = {
            self.RIGHT_TAB_FILES: "fa5s.folder-open",
            self.RIGHT_TAB_OBSERVABILITY: "fa5s.chart-line",
            self.RIGHT_TAB_SUB_AGENTS: "fa5s.project-diagram",
        }
        for tab_index, btn in self.context_rail_buttons.items():
            active = self.right_drawer_open and self.right_drawer_tab == tab_index
            hinted = tab_index in self.context_available_tabs
            btn.setChecked(active)
            btn.setStyleSheet(apple_tool_button_style(active or hinted))
            color = DesignTokens.primary if active or hinted else DesignTokens.text_secondary
            btn.setIcon(qta.icon(icons.get(tab_index, "fa5s.circle"), color=color))

    def set_observability_section(self, index):
        if not hasattr(self, "observability_content_stack"):
            return
        count = self.observability_content_stack.count()
        if count <= 0:
            return
        index = max(0, min(index, count - 1))
        log_sub_agent_runtime(
            "ui_observability_section_begin",
            index=index,
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
        )
        try:
            self.observability_section_index = index
            if index in {getattr(self, "OBS_SECTION_PROMPT", -1), getattr(self, "OBS_SECTION_LOG", -1)}:
                self.refresh_observability_view(self.current_session_id)
            self.observability_content_stack.setCurrentIndex(index)
            self._on_context_surface_changed()
            for btn_index, btn in enumerate(getattr(self, "observability_segment_buttons", [])):
                btn.setChecked(btn_index == index)
            log_sub_agent_runtime(
                "ui_observability_section_done",
                index=index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_section_failed",
                index=index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
                traceback=traceback.format_exc(),
            )

    def _prompt_tool_menu_entries(self):
        return [
            ("add_files", "添加文件"),
            ("add_agent", "添加智能体"),
            ("select_skills", "指定能力"),
            ("clarify_mode", "反问模式"),
        ]

    def _normalize_prompt_file_paths(self, paths):
        normalized = []
        seen = set()
        for path in paths or []:
            if not path or not os.path.isfile(path):
                continue
            norm = os.path.normpath(path)
            key = os.path.normcase(norm)
            if key in seen:
                continue
            seen.add(key)
            normalized.append(norm)
        return normalized

    def _is_supported_image_attachment(self, path):
        mime_type, _encoding = mimetypes.guess_type(path)
        return str(mime_type or "").strip().lower() in {
            "image/png",
            "image/jpeg",
            "image/webp",
            "image/gif",
        }

    def _selected_model_supports_vision(self):
        profile = self.config_manager.get_model_profile(self.config_manager.get_selected_model_id())
        if not isinstance(profile, dict):
            return False
        return bool(profile.get("supports_vision", False))

    def _resolve_text_image_references(self, user_text, existing_paths=None):
        if not getattr(self, "workspace_dir", None):
            return []
        existing_keys = {
            os.path.normcase(os.path.normpath(path))
            for path in (existing_paths or [])
        }
        candidates = []
        text = str(user_text or "")
        for match in re.finditer(r"(?P<path>[^\s\"'，。；;：:]+?\.(?:png|jpg|jpeg|webp|gif))", text, re.IGNORECASE):
            candidate = match.group("path").strip("()[]{}<>\"'`")
            if candidate:
                candidates.append(candidate)

        resolved = []
        seen = set(existing_keys)
        workspace_root = os.path.abspath(self._workspace_dir_for_state())

        def add_path(path):
            normalized = os.path.normpath(os.path.abspath(path))
            key = os.path.normcase(normalized)
            if key in seen or not os.path.isfile(normalized) or not self._is_supported_image_attachment(normalized):
                return
            try:
                if os.path.commonpath([workspace_root, normalized]) != workspace_root:
                    return
            except Exception:
                return
            seen.add(key)
            resolved.append(normalized)

        for candidate in candidates:
            if os.path.isabs(candidate):
                add_path(candidate)
            else:
                add_path(os.path.join(workspace_root, candidate))

        missing_names = {
            os.path.basename(candidate)
            for candidate in candidates
            if candidate and not os.path.isabs(candidate)
        }
        if missing_names:
            scanned = 0
            for root, _dirs, files in os.walk(workspace_root):
                scanned += 1
                if scanned > 800:
                    break
                for filename in files:
                    if filename in missing_names:
                        add_path(os.path.join(root, filename))
        return resolved

    def _prompt_file_items(self, paths):
        items = []
        seen = set()
        for raw_path in paths or []:
            path = os.path.normpath(str(raw_path or "").strip())
            if not path:
                continue
            key = os.path.normcase(path)
            if key in seen:
                continue
            seen.add(key)
            items.append({"path": path, "name": os.path.basename(path) or path})
        return items

    def _current_prompt_files(self, session_id=None):
        state = self.get_session(session_id)
        return list(getattr(state, "prompt_files", []) or []) if state else []

    def _set_prompt_files(self, paths, session_id=None, refresh=True):
        state = self.get_session(session_id)
        normalized = self._normalize_prompt_file_paths(paths)
        if state:
            state.prompt_files = normalized
        if refresh and (session_id is None or session_id == self.current_session_id):
            self.refresh_prompt_file_chips(session_id)
        return normalized

    def refresh_prompt_file_chips(self, session_id=None):
        if not hasattr(self, "prompt_files_section") or not hasattr(self, "prompt_files_row"):
            return
        files = self._current_prompt_files(session_id)
        while self.prompt_files_row.count():
            item = self.prompt_files_row.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        if not files:
            self.prompt_files_section.setVisible(False)
            return
        self.prompt_files_hint.setText(f"用户添加的文件 ({len(files)})")
        for path in files:
            chip = FileChip(path, removable=True)
            chip.removeRequested.connect(self._remove_prompt_file)
            self.prompt_files_row.addWidget(chip)
        self.prompt_files_row.addStretch()
        self.prompt_files_section.setVisible(True)

    def _remove_prompt_file(self, path):
        remaining = [
            item
            for item in self._current_prompt_files()
            if os.path.normcase(item) != os.path.normcase(os.path.normpath(path))
        ]
        self._set_prompt_files(remaining)

    def _clear_prompt_files(self, session_id=None):
        self._set_prompt_files([], session_id=session_id, refresh=True)

    def _add_prompt_files(self, paths):
        file_paths = self._normalize_prompt_file_paths(paths)
        if not file_paths or not hasattr(self, "input_field"):
            return []

        if not self._workspace_dir_for_state():
            parent_dir = os.path.dirname(file_paths[0])
            if parent_dir:
                self.load_workspace(parent_dir)

        existing = self._current_prompt_files()
        self._set_prompt_files(existing + file_paths)
        self.input_field.moveCursor(QTextCursor.End)
        self.input_field.ensureCursorVisible()
        self.input_field.setFocus()
        if hasattr(self.input_field, "adjustHeight"):
            self.input_field.adjustHeight()
        self.set_context_tab_hint(self.RIGHT_TAB_FILES, True)
        return file_paths

    def _append_files_to_input(self, paths):
        return self._add_prompt_files(paths)

    def select_files_for_prompt(self):
        start_dir = self._workspace_dir_for_state() or self.config_manager.get("default_workspace", "") or ""
        file_paths, _selected_filter = QFileDialog.getOpenFileNames(
            self,
            "选择文件",
            start_dir,
            "所有文件 (*.*)",
        )
        self._add_prompt_files(file_paths)

    def _build_user_added_files_prompt(self, file_paths):
        normalized = self._normalize_prompt_file_paths(file_paths)
        if not normalized:
            return ""
        lines = [
            "[用户添加的文件]",
            "以下文件由用户通过“添加文件”手动附加，请优先视为本轮任务的重要输入：",
        ]
        for path in normalized:
            lines.append(f"- 文件名: {os.path.basename(path) or path}")
            lines.append(f"  路径: {path}")
        return "\n".join(lines)

    def _build_user_message_payload(self, user_text, file_paths, supports_vision=False):
        display_text = str(user_text or "").strip()
        normalized_files = self._normalize_prompt_file_paths(file_paths)
        referenced_images = self._resolve_text_image_references(display_text, normalized_files)
        if referenced_images:
            normalized_files = self._normalize_prompt_file_paths(normalized_files + referenced_images)
        image_paths = [path for path in normalized_files if self._is_supported_image_attachment(path)]
        regular_files = [path for path in normalized_files if path not in image_paths]
        content_blocks = []
        if normalized_files:
            content_blocks.append(self._build_user_added_files_prompt(normalized_files))
        if display_text:
            content_blocks.append(display_text)
        content = "\n\n".join([block for block in content_blocks if block]).strip()
        content_parts = []
        if display_text:
            content_parts.append({"type": "text", "text": display_text})
        for path in image_paths:
            content_parts.append(
                {
                    "type": "input_image",
                    "path": path,
                    "name": os.path.basename(path) or path,
                    "source": "user_added",
                }
            )
        for path in regular_files:
            content_parts.append(
                {
                    "type": "input_file",
                    "path": path,
                    "name": os.path.basename(path) or path,
                    "source": "user_added",
                }
            )
        meta = {}
        if display_text:
            meta["display_content"] = display_text
        if normalized_files:
            meta["user_added_files"] = normalized_files
        if image_paths:
            meta["user_added_images"] = image_paths
            meta["vision_requested"] = bool(supports_vision)
        if referenced_images:
            meta["workspace_referenced_images"] = referenced_images
        return {
            "content": content,
            "display_content": display_text,
            "attachments": self._prompt_file_items(normalized_files),
            "content_parts": content_parts or None,
            "meta": meta or None,
        }

    def _message_user_attachments(self, message):
        if not isinstance(message, dict):
            return []
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        meta_paths = meta.get("user_added_files")
        if isinstance(meta_paths, list):
            return self._prompt_file_items(meta_paths)
        attachments = []
        for part in message.get("content_parts") or []:
            if not isinstance(part, dict):
                continue
            part_type = str(part.get("type") or "").strip().lower()
            if part_type not in {"input_file", "input_image"}:
                continue
            path = str(part.get("path") or "").strip()
            if not path:
                continue
            attachments.append(path)
        return self._prompt_file_items(attachments)

    def _message_display_content(self, message):
        if not isinstance(message, dict):
            return ""
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        display = meta.get("display_content")
        if display is not None:
            return str(display)
        return str(message.get("content") or "")

    def _new_message_id(self):
        return uuid.uuid4().hex

    def _session_is_busy(self, state):
        return bool(
            state
            and (
                (getattr(state, "llm_worker", None) and state.llm_worker.isRunning())
                or (getattr(state, "code_worker", None) and state.code_worker.isRunning())
                or getattr(state, "daemon_running", False)
            )
        )

    def _can_rewrite_session_from_message(self, state):
        if not state:
            return (False, "找不到当前会话。")
        if getattr(state, "history_loading", False) or not getattr(state, "history_loaded", True):
            return (False, "历史消息仍在加载，请稍后再试。")
        if self._session_is_busy(state):
            return (False, "当前会话正在运行，请先停止任务后再编辑或删除消息。")
        return (True, "")

    def _message_attachment_paths(self, message):
        attachments = self._message_user_attachments(message)
        return self._normalize_prompt_file_paths(
            [item.get("path") for item in attachments if isinstance(item, dict) and item.get("path")]
        )

    def _find_message_by_id(self, messages, message_id):
        target_id = str(message_id or "").strip()
        if not target_id:
            return None
        for msg in messages or []:
            if not isinstance(msg, dict):
                continue
            if str(msg.get("id") or "").strip() == target_id:
                return msg
        return None

    def _assistant_source_message_id_from_messages(self, messages):
        for msg in reversed(messages or []):
            if not isinstance(msg, dict):
                continue
            if (msg.get("role") or "") != "assistant":
                continue
            message_id = str(msg.get("id") or "").strip()
            if message_id:
                return message_id
        return ""

    def _render_rewritten_session(self, state, messages):
        if not state:
            return
        self.clear_chat_layout(state.chat_layout)
        state.empty_state = None
        state.messages = self.chat_storage.normalize_messages(copy.deepcopy(messages or []))
        state.tool_cards = {}
        state.pending_tool_results = {}
        state.last_agent_bubble = None
        state.temp_thinking_bubble = None
        self._rebuild_session_render_spans(state)
        state.displayed_render_count = len(state.render_items)
        if state.messages:
            self.render_message_batch(state.messages, state.session_id, animate=False)
        else:
            self._render_initial_session_history(state)

    def edit_user_message_inline(self, session_id, message_id, edited_text):
        session_id = str(session_id or "").strip()
        message_id = str(message_id or "").strip()
        if not session_id or not message_id:
            return False
        state = self.get_session(session_id)
        allowed, message = self._can_rewrite_session_from_message(state)
        if not allowed:
            self.add_system_toast(message, "warning", session_id=session_id, auto_close_ms=3200)
            return False
        source_message = self._find_message_by_id(getattr(state, "messages", []), message_id)
        if not isinstance(source_message, dict) or (source_message.get("role") or "") != "user":
            self.add_system_toast("只能编辑用户消息。", "warning", session_id=session_id, auto_close_ms=3200)
            return False

        edited_text = str(edited_text or "").strip()
        prompt_files = self._message_attachment_paths(source_message)
        if not edited_text and not prompt_files:
            self.add_system_toast("消息内容不能为空。", "warning", session_id=session_id, auto_close_ms=3200)
            return False

        self.save_chat_history(session_id=session_id, flush=True)
        messages = list(getattr(state, "messages", []) or [])
        target_index = next(
            (index for index, item in enumerate(messages) if str(item.get("id") or "").strip() == message_id),
            -1,
        )
        if target_index < 0:
            self.add_system_toast("找不到要编辑的消息。", "warning", session_id=session_id, auto_close_ms=3200)
            return False
        self._render_rewritten_session(state, messages[:target_index])
        submitted = self._submit_session_request(
            state,
            edited_text,
            prompt_files,
            check_duplicates=False,
            clear_current_input=False,
        )
        if not submitted:
            self._render_rewritten_session(state, messages)
            self.add_system_toast("编辑后的消息未能提交。", "warning", session_id=session_id, auto_close_ms=3200)
            return False
        self.save_chat_history(session_id=session_id)
        self.refresh_history_list()
        self.add_system_toast("已更新消息并重新生成", "success", session_id=session_id, auto_close_ms=3200)
        return True

    def delete_user_message_in_place(self, session_id, message_id):
        session_id = str(session_id or "").strip()
        message_id = str(message_id or "").strip()
        if not session_id or not message_id:
            return False
        state = self.get_session(session_id)
        allowed, message = self._can_rewrite_session_from_message(state)
        if not allowed:
            self.add_system_toast(message, "warning", session_id=session_id, auto_close_ms=3200)
            return False
        source_message = self._find_message_by_id(getattr(state, "messages", []), message_id)
        if not isinstance(source_message, dict) or (source_message.get("role") or "") != "user":
            self.add_system_toast("只能删除用户消息。", "warning", session_id=session_id, auto_close_ms=3200)
            return False

        confirm = QMessageBox.question(
            self,
            "确认删除消息",
            "仅删除这条用户消息，后续内容会保留。是否继续？",
        )
        if confirm != QMessageBox.Yes:
            return False

        self.save_chat_history(session_id=session_id, flush=True)
        messages = list(getattr(state, "messages", []) or [])
        remaining_messages = [
            item for item in messages
            if str(item.get("id") or "").strip() != message_id
        ]
        if len(remaining_messages) == len(messages):
            self.add_system_toast("找不到要删除的消息。", "warning", session_id=session_id, auto_close_ms=3200)
            return False
        self._render_rewritten_session(state, remaining_messages)
        self.save_chat_history(session_id=session_id, flush=True)
        self.refresh_history_list()
        self.add_system_toast("已删除消息，后续内容保持不变。", "success", session_id=session_id, auto_close_ms=3200)
        if hasattr(self, "input_field") and self.input_field:
            self.input_field.setFocus()
        return True

    def _should_block_send_for_sop(self, state):
        return bool(state and is_sop_awaiting_confirmation(getattr(state, "sop_run", None)))

    def show_prompt_tool_menu(self):
        menu = create_styled_menu(self)
        add_files = QAction(qta.icon('fa5s.paperclip', color='#4b5563'), "添加文件", self)
        add_files.triggered.connect(self.select_files_for_prompt)
        menu.addAction(add_files)
        add_agent_menu = menu.addMenu(qta.icon('fa5s.user-astronaut', color='#4b5563'), "添加智能体")
        self._populate_agent_menu(add_agent_menu)
        select_skills_action = QAction(qta.icon('fa5s.puzzle-piece', color='#4b5563'), "指定能力", self)
        select_skills_action.triggered.connect(self.open_session_skill_picker)
        menu.addAction(select_skills_action)
        menu.addAction(self.clarify_mode_action)
        menu.exec(self.tool_menu_btn.mapToGlobal(self.tool_menu_btn.rect().bottomLeft()))

    def refresh_model_selector(self):
        if not hasattr(self, "model_select_btn"):
            return
        selected_id = self.config_manager.get_selected_model_id()
        profiles = self.config_manager.iter_model_profiles()
        selected = next((item for item in profiles if item.get("id") == selected_id), None)
        if selected is None and profiles:
            selected = profiles[0]
            selected_id = selected.get("id")
        menu = QMenu(self.model_select_btn)
        effort_labels = {
            "low": "低",
            "medium": "中",
            "high": "高",
            "xhigh": "超高",
            "max": "极限",
        }
        efforts = normalize_reasoning_efforts((selected or {}).get("reasoning_efforts"))
        current_effort = normalize_reasoning_effort((selected or {}).get("reasoning_effort"), efforts)
        if efforts:
            menu.addSection("推理")
            for effort in efforts:
                action = menu.addAction(effort_labels.get(effort, effort))
                action.setCheckable(True)
                action.setChecked(effort == current_effort)
                action.triggered.connect(
                    lambda _checked=False, value=effort: self.on_reasoning_effort_selected(value)
                )
            menu.addSeparator()
        model_menu = menu.addMenu("模型") if efforts else menu
        if not efforts:
            model_menu.addSection("模型")
        for profile in profiles:
            display_name = profile.get("display_name") or profile.get("model_name") or "模型"
            channel_name = profile.get("channel_display_name") or profile.get("provider_display_name") or profile.get("provider") or ""
            label = f"{channel_name} / {display_name}" if channel_name else display_name
            action = model_menu.addAction(label)
            action.setCheckable(True)
            action.setChecked(profile.get("id") == selected_id)
            action.setToolTip(" / ".join(filter(None, (profile.get("model_name", ""), profile.get("base_url", "")))))
            action.triggered.connect(
                lambda _checked=False, model_id=profile.get("id"): self.on_model_selection_changed(model_id)
            )
        self.model_select_btn.setMenu(menu)
        if selected:
            display_name = selected.get("display_name") or selected.get("model_name") or "模型"
            channel_name = selected.get("channel_display_name") or selected.get("provider_display_name") or selected.get("provider") or ""
            label = f"{channel_name} / {display_name}" if channel_name else display_name
            if current_effort:
                label += f" · {effort_labels.get(current_effort, current_effort)}"
            self.model_select_btn.setText(label)
            self.model_select_btn.setToolTip(" / ".join(filter(None, (selected.get("model_name", ""), selected.get("base_url", "")))))
        else:
            self.model_select_btn.setText("未配置模型")

    def on_model_selection_changed(self, model_id):
        if model_id and self.config_manager.set_selected_model_id(model_id):
            self.refresh_model_selector()
            self.refresh_context_badges()

    def on_reasoning_effort_selected(self, effort):
        model_id = self.config_manager.get_selected_model_id()
        if self.config_manager.set_model_reasoning_effort(model_id, effort):
            self.refresh_model_selector()

    def _selected_reasoning_effort(self):
        profile = self.config_manager.get_model_profile(self.config_manager.get_selected_model_id())
        if not isinstance(profile, dict):
            return ""
        efforts = normalize_reasoning_efforts(profile.get("reasoning_efforts"))
        return normalize_reasoning_effort(profile.get("reasoning_effort"), efforts)

    def update_ui_state_for_workspace(self):
        if self.workspace_dir:
            self.input_field.setEnabled(True)
            self.input_field.setPlaceholderText("例如：把这个文件夹里的图片按日期分类")
            self.action_btn.setEnabled(True)
            self.ws_label.setStyleSheet(f"color: {DesignTokens.success_text}; font-weight: 600;")
        else:
            # Keep input enabled but change placeholder to guide user
            self.input_field.setPlaceholderText("📁 先选择或拖拽一个文件夹到这里...")
            # Disable send button
            self.action_btn.setEnabled(False)
            self.ws_label.setStyleSheet(f"color: {DesignTokens.text_secondary}; font-weight: 500;")

        self.refresh_context_badges()

    def update_ui_state_for_workspace(self):
        if self.workspace_dir:
            self.input_field.setEnabled(True)
            self.input_field.setPlaceholderText("描述你要完成的任务，例如：整理本周截图并生成周报摘要")
            self.action_btn.setEnabled(True)
            self.ws_label.setStyleSheet(apple_inline_project_chip_style(True))
        else:
            self.input_field.setEnabled(True)
            self.input_field.setPlaceholderText("直接开始对话；需要处理文件时再连接项目")
            self.action_btn.setEnabled(True)
            self.ws_label.setStyleSheet(apple_inline_project_chip_style(False))
            self.ws_label.setText("未连接项目 · 纯对话")
        self.refresh_project_selector()
        self.refresh_context_badges()

    def refresh_context_badges(self, session_id=None):
        state = self.get_session(session_id)
        profile = self.config_manager.get_model_profile()
        provider_text = profile.get("provider_display_name") if profile else self.config_manager.get("llm_provider", "openai")
        model_name = profile.get("display_name") or profile.get("model_name") if profile else self.config_manager.get("model_name", DEFAULT_DEEPSEEK_MODEL)
        if getattr(self, "daemon_available", False):
            connection_text = "Daemon Ready"
        elif getattr(self, "daemon_bootstrapping", False):
            connection_text = "Connecting"
        else:
            connection_text = "Local Agent"
        self.model_badge.setText(f"{provider_text} | {model_name} | {connection_text}")

        if self.config_manager.get_god_mode():
            self.security_badge.setText("Extended Access")
            self.security_badge.setStyleSheet(
                f"background: {DesignTokens.warning_bg}; color: {DesignTokens.warning_text}; "
                f"border-radius: 12px; padding: 4px 10px; font-size: 11px; font-weight: 600;"
            )
        else:
            self.security_badge.setText("Workspace Only")
            self.security_badge.setStyleSheet(
                f"background: {DesignTokens.success_bg}; color: {DesignTokens.success_text}; "
                f"border-radius: 12px; padding: 4px 10px; font-size: 11px; font-weight: 600;"
            )

        phase = "Idle"
        if state:
            phase = getattr(state, "run_phase", "Idle") or "Idle"
        self.phase_badge.setText(f"Phase: {phase}")

        has_workspace = bool(self._workspace_dir_for_state(state))
        has_clarify_context = bool(
            state
            and (
                state.clarify_mode_enabled
                or bool(getattr(state, "pending_clarify_questions", []))
            )
        )
        has_observability_context = bool(
            state
            and (
                getattr(state, "observability_events", [])
                or getattr(state, "system_prompt_text", "")
                or getattr(state, "system_prompt_appends", [])
            )
        )
        has_sop_context = bool(state and normalize_sop_run(getattr(state, "sop_run", None)))
        has_context = bool(state and (state.step_records or state.has_file_changes or has_clarify_context or has_observability_context or has_sop_context))
        self.context_available_tabs = set()
        if has_workspace:
            self.context_available_tabs.add(self.RIGHT_TAB_FILES)
            self.context_available_tabs.add(self.RIGHT_TAB_DELIVERABLES)
        if has_observability_context or has_context:
            self.context_available_tabs.add(self.RIGHT_TAB_OBSERVABILITY)
        if state and (getattr(state, "sub_agent_events", []) or getattr(state, "persisted_agents", [])):
            self.context_available_tabs.add(self.RIGHT_TAB_SUB_AGENTS)
        self.update_context_rail_badges()
        if state and state.session_id == self.current_session_id:
            self.refresh_clarify_controls(state.session_id)
            self.refresh_sop_controls(state.session_id)

    def _extract_pending_clarify_questions_from_args(self, args_obj):
        if not isinstance(args_obj, dict):
            return []
        return normalize_pending_clarify_questions(args_obj.get("questions"))

    def _session_clarify_meta(self, state):
        if not state:
            return {}
        return {
            "clarify_mode_enabled": bool(getattr(state, "clarify_mode_enabled", False)),
            "clarify_phase": normalize_clarify_phase(
                getattr(state, "clarify_phase", ""),
                default=derive_clarify_phase(
                    getattr(state, "clarify_mode_enabled", False),
                    getattr(state, "clarify_mode_state", CLARIFY_MODE_EXPLORING),
                ),
            ),
            "clarify_mode_state": normalize_clarify_phase(
                getattr(state, "clarify_mode_state", CLARIFY_MODE_EXPLORING),
                default=CLARIFY_MODE_EXPLORING,
            ),
            "pending_clarify_questions": normalize_pending_clarify_questions(
                getattr(state, "pending_clarify_questions", [])
            ),
        }

    def _session_selected_skills_meta(self, state):
        if not state:
            return {}
        return {
            "selected_skill_names": normalize_selected_skill_names(
                getattr(state, "selected_skill_names", [])
            )
        }

    def _session_sop_meta(self, state):
        if not state:
            return {}
        return {
            "sop_run": normalize_sop_run(getattr(state, "sop_run", None))
        }

    def _active_sop_template(self, state):
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        if not sop_run:
            return None
        return self.config_manager.get_sop_template(sop_run.get("template_id"))

    def _resolve_sop_default_profile(self, state):
        template = self._active_sop_template(state)
        if not template:
            return None
        profile_id = str(template.get("default_agent_profile_id") or "").strip()
        if not profile_id:
            return None
        profile = self.config_manager.get_agent_profile(profile_id)
        if not profile or not bool(profile.get("enabled", True)):
            return None
        return profile

    def _effective_sop_skill_names(self, state, extra_skill_names=None):
        names = []
        seen = set()
        sources = [
            getattr(state, "selected_skill_names", []),
        ]
        template = self._active_sop_template(state)
        if template:
            sources.append(template.get("skill_names") or [])
        if extra_skill_names:
            sources.append(extra_skill_names)
        for source in sources:
            for skill_name in normalize_selected_skill_names(source):
                if skill_name in seen:
                    continue
                seen.add(skill_name)
                names.append(skill_name)
        return names

    def _remove_sop_confirmation_bar(self, state):
        bar = getattr(state, "sop_confirmation_bar", None) if state else None
        if bar is not None and _qt_object_alive(bar):
            bar.deleteLater()
        if state is not None:
            state.sop_confirmation_bar = None

    def _sync_sop_confirmation_bar(self, state, sop_run, current_step, running=False):
        if not state:
            return
        awaiting = bool(sop_run and sop_run.get("status") == SOP_RUN_STATUS_AWAITING_CONFIRMATION)
        if not awaiting or state.session_id != self.current_session_id:
            self._remove_sop_confirmation_bar(state)
            return
        bar = getattr(state, "sop_confirmation_bar", None)
        if bar is None or not _qt_object_alive(bar):
            bar = SopConfirmationBar()
            bar.confirmRequested.connect(self.confirm_current_sop_step)
            bar.rerunRequested.connect(self.rerun_current_sop_step)
            bar.skipRequested.connect(self.skip_current_sop_step)
            bar.apply_dynamic_width(self.dynamic_message_width)
            state.sop_confirmation_bar = bar
            if getattr(state, "empty_state", None) and state.empty_state.isVisible():
                state.empty_state.setVisible(False)
            state.chat_layout.insertWidget(state.chat_layout.count() - 1, bar, 0, Qt.AlignHCenter)
        bar.update_state(
            sop_run,
            current_step=current_step,
            allow_skip=bool(current_step and current_step.get("allow_skip")),
            running=running,
        )
        bar.apply_dynamic_width(self.dynamic_message_width)

    def refresh_sop_controls(self, session_id=None):
        state = self.get_session(session_id)
        if not state or state.session_id != self.current_session_id:
            return
        if not hasattr(self, "sop_badge"):
            self._remove_sop_confirmation_bar(state)
            return
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        running = bool(
            (state.llm_worker and state.llm_worker.isRunning())
            or (state.code_worker and state.code_worker.isRunning())
            or getattr(state, "daemon_running", False)
        )
        if not sop_run:
            self.sop_badge.setVisible(False)
            self._remove_sop_confirmation_bar(state)
            if hasattr(self, "sop_progress_label"):
                self.sop_progress_label.setText("尚未绑定自动化")
                self.sop_intro_label.setText("当前会话未绑定自动化")
                self.sop_status_label.setText("未启动")
                self.sop_status_label.setStyleSheet(apple_status_chip_style("pending", subtle=True))
                self.sop_step_list.clear()
                self.sop_current_step_label.setText("当前步骤")
                self.sop_instruction_label.setText("绑定自动化后，这里会显示当前步骤的执行要求。")
                self.sop_success_label.setText("")
                self.sop_confirm_btn.setEnabled(False)
                self.sop_rerun_btn.setEnabled(False)
                self.sop_skip_btn.setEnabled(False)
            return
        state.sop_run = sop_run
        current_step = get_current_step(sop_run)
        badge_text = f" 自动化 · {sop_run.get('template_name') or '未命名自动化'}"
        if current_step:
            badge_text = f"{badge_text} · {preview_text(current_step.get('title') or '当前步骤', limit=16)}"
        self.sop_badge.setText(badge_text)
        self.sop_badge.setToolTip(
            f"当前自动化：{sop_run.get('template_name') or '未命名自动化'}"
        )
        self.sop_badge.setVisible(True)
        self.sop_badge.setEnabled(not running)
        if hasattr(self, "sop_progress_label"):
            self.sop_progress_label.setText(
                f"{sop_run.get('template_name') or '未命名自动化'} · 第 {min(sop_run.get('current_step_index', 0) + 1, max(len(sop_run.get('steps') or []), 1))} 步"
            )

        if hasattr(self, "sop_step_list"):
            self.sop_step_list.blockSignals(True)
            self.sop_step_list.clear()
            for index, step in enumerate(sop_run.get("steps") or []):
                status = str(step.get("status") or "")
                icon_name = "fa5s.circle"
                icon_color = DesignTokens.text_tertiary
                if status in {"completed", "skipped"}:
                    icon_name = "fa5s.check-circle" if status == "completed" else "fa5s.forward"
                    icon_color = DesignTokens.status_success if status == "completed" else DesignTokens.warning_text
                elif index == sop_run.get("current_step_index"):
                    icon_name = "fa5s.play-circle"
                    icon_color = DesignTokens.status_running
                item = QListWidgetItem(
                    qta.icon(icon_name, color=icon_color),
                    f"{index + 1}. {step.get('title') or f'步骤 {index + 1}'}\n{status_label_text(status or ('active' if index == sop_run.get('current_step_index') else 'pending'))}",
                )
                item.setToolTip(step.get("success_criteria") or "")
                self.sop_step_list.addItem(item)
            if self.sop_step_list.count():
                self.sop_step_list.setCurrentRow(min(sop_run.get("current_step_index", 0), self.sop_step_list.count() - 1))
            self.sop_step_list.blockSignals(False)

        intro = sop_run.get("template_description") or "当前会话正在按自动化模板逐步执行。"
        if sop_run.get("status") == SOP_RUN_STATUS_COMPLETED:
            intro = f"{intro}\n当前自动化已完成。"
            if hasattr(self, "sop_status_label"):
                self.sop_status_label.setText("已完成")
                self.sop_status_label.setStyleSheet(apple_status_chip_style("completed"))
        elif sop_run.get("status") == SOP_RUN_STATUS_AWAITING_CONFIRMATION:
            intro = f"{intro}\n当前步骤已完成，等待你确认。"
            if hasattr(self, "sop_status_label"):
                self.sop_status_label.setText("等待确认")
                self.sop_status_label.setStyleSheet(apple_status_chip_style("pending"))
        elif running:
            if hasattr(self, "sop_status_label"):
                self.sop_status_label.setText("执行中")
                self.sop_status_label.setStyleSheet(apple_status_chip_style("running"))
        else:
            if hasattr(self, "sop_status_label"):
                self.sop_status_label.setText("待推进")
                self.sop_status_label.setStyleSheet(apple_status_chip_style("pending", subtle=True))
        if hasattr(self, "sop_intro_label"):
            self.sop_intro_label.setText(intro)

        if current_step:
            effective_mode = resolve_step_advance_mode(sop_run, current_step)
            mode_text = "自动推进" if effective_mode == SOP_ADVANCE_MODE_AUTO else "人工确认"
            if hasattr(self, "sop_current_step_label"):
                self.sop_current_step_label.setText(
                    f"当前步骤 {sop_run.get('current_step_index', 0) + 1} / {len(sop_run.get('steps') or [])}: {current_step.get('title') or '未命名步骤'}"
                )
                instructions = current_step.get("instructions") or "未填写执行指令。"
                self.sop_instruction_label.setText(f"{instructions}\n推进方式：{mode_text}")
                success_text = current_step.get("success_criteria") or "未填写成功标准。"
                self.sop_success_label.setText(f"成功标准：{success_text}")
        else:
            if hasattr(self, "sop_current_step_label"):
                self.sop_current_step_label.setText("当前步骤")
                self.sop_instruction_label.setText("当前没有可执行步骤。")
                self.sop_success_label.setText("")

        allow_actions = sop_run.get("status") == SOP_RUN_STATUS_AWAITING_CONFIRMATION and not running
        if hasattr(self, "sop_confirm_btn"):
            self.sop_confirm_btn.setEnabled(allow_actions)
            self.sop_rerun_btn.setEnabled(allow_actions)
            self.sop_skip_btn.setEnabled(allow_actions and bool(current_step and current_step.get("allow_skip")))
        self._sync_sop_confirmation_bar(state, sop_run, current_step, running=running)

    def _mark_sop_step_done_for_confirmation(self, state, executor="", content="", agent_profile=None):
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        if not sop_run or is_sop_completed(sop_run):
            return False
        execution_info = {
            "finished_at": int(time.time()),
            "executor": executor or ((sop_run.get("last_execution") or {}).get("executor") or "main_agent"),
            "content": str(content or "").strip(),
        }
        if agent_profile:
            execution_info["agent_profile_id"] = agent_profile.get("id") or ""
            execution_info["agent_profile_name"] = agent_profile.get("name") or ""
        state.sop_run = mark_step_awaiting_confirmation(sop_run, execution_info=execution_info)
        self.save_chat_history(session_id=state.session_id)
        self.refresh_sop_controls(state.session_id)
        self.refresh_context_badges(state.session_id)
        return True

    def _current_sop_template_for_state(self, state):
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        if not sop_run:
            return None
        return self.config_manager.get_sop_template(sop_run.get("template_id"))

    def _mark_session_automation_awaiting_confirmation(self, state):
        if not state or not getattr(state, "automation_run_id", ""):
            return
        summary = self._automation_summary_from_state(state)
        self._finalize_automation_history_record(
            state.automation_run_id,
            AUTOMATION_HISTORY_STATUS_AWAITING_CONFIRMATION,
            summary=summary,
        )

    def _start_sop_executor_worker(self, state):
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        if not state or not sop_run:
            return False
        worker = SopStepExecutorWorker(
            state.session_id,
            sop_run,
            self._workspace_dir_for_state(state),
            parent=self,
        )
        state.sop_executor_worker = worker
        worker.finished_signal.connect(self._handle_sop_executor_finished)
        worker.finished.connect(lambda sid=state.session_id: self._cleanup_sop_executor_worker(sid))
        worker.start()
        return True

    def _cleanup_sop_executor_worker(self, session_id):
        state = self.get_session(session_id)
        if not state:
            return
        worker = getattr(state, "sop_executor_worker", None)
        if worker and not worker.isRunning():
            try:
                worker.deleteLater()
            except Exception:
                pass
        state.sop_executor_worker = None

    def _append_sop_executor_result_message(self, state, result):
        if not state:
            return
        payload = dict(result or {})
        message_id = self._new_message_id()
        executor_type = str(payload.get("executor_type") or "sop_executor").strip()
        ok = bool(payload.get("ok"))
        heading = "SOP 执行完成" if ok else "SOP 执行失败"
        content = str(payload.get("content") or "").strip() or "(No output)"
        message_text = f"{heading}（{executor_type}）\n{content}"
        state.messages.append(
            {
                "id": message_id,
                "role": "assistant",
                "content": message_text,
                "meta": {
                    "sop_executor_result": True,
                    "sop_executor_type": executor_type,
                },
            }
        )
        self._rebuild_session_render_spans(state)
        state.displayed_count = min(len(state.messages), state.displayed_count + 1)
        state.displayed_render_count = len(state.render_items)
        self.save_chat_history(session_id=state.session_id)
        if state.session_id == self.current_session_id:
            self.add_chat_bubble(
                "Assistant",
                message_text,
                animate=False,
                force_scroll=True,
                source_message_id=message_id,
            )

    def _handle_sop_executor_finished(self, result, session_id):
        state = self.get_session(session_id)
        if not state:
            return
        payload = dict(result or {})
        ok = bool(payload.get("ok"))
        self._append_sop_executor_result_message(state, payload)
        metadata = {
            "executor_type": payload.get("executor_type") or "",
            "exit_code": payload.get("exit_code"),
            "stdout": payload.get("stdout") or "",
            "stderr": payload.get("stderr") or "",
            "error": payload.get("error") or "",
            "duration_seconds": payload.get("duration_seconds"),
        }
        self._finalize_sop_execution_step(
            state,
            executor=payload.get("executor") or "sop_executor",
            content=payload.get("content") or "",
            output_status="completed" if ok else "error",
            metadata=metadata,
            allow_auto_advance=ok,
        )

    def _dispatch_current_sop_step(
        self,
        state,
        *,
        linked_template=None,
        create_user_bubble=True,
        set_running=True,
        submitted_at=None,
    ):
        if not state:
            return False
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        if not sop_run or is_sop_completed(sop_run):
            return False
        step_payload = build_step_execution_request(sop_run)
        step_content = str(step_payload.get("content") or "").strip()
        if not step_content:
            return False
        step_display = str(step_payload.get("display_content") or "").strip() or step_content
        current_step = get_current_step(sop_run)
        current_step_index = int(sop_run.get("current_step_index", 0))
        executor_type = str((current_step or {}).get("executor_type") or SOP_EXECUTOR_AGENT).strip() or SOP_EXECUTOR_AGENT
        if set_running:
            started_at = int(submitted_at or time.time())
            state.sop_run = mark_step_running(
                sop_run,
                {
                    "started_at": started_at,
                    "executor": "main_agent" if executor_type == SOP_EXECUTOR_AGENT else executor_type,
                    "trigger_message": step_content,
                },
            )
            sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        message_meta = {
            "display_content": step_display,
            "sop_step_dispatch": True,
            "sop_step_index": current_step_index,
            "sop_step_title": (current_step or {}).get("title") or "",
            "sop_executor_type": executor_type,
        }
        message_id = self._new_message_id()
        state.messages.append(
            {
                "id": message_id,
                "role": "user",
                "content": step_content,
                "meta": message_meta,
            }
        )
        self._rebuild_session_render_spans(state)
        state.displayed_count = min(len(state.messages), state.displayed_count + 1)
        state.displayed_render_count = len(state.render_items)
        if create_user_bubble and state.session_id == self.current_session_id:
            self.add_chat_bubble(
                "User",
                step_display,
                animate=False,
                force_scroll=True,
                source_message_id=message_id,
            )

        if executor_type != SOP_EXECUTOR_AGENT:
            self.set_session_phase("Executing SOP step", state.session_id)
            self.set_session_status("running", state.session_id)
            return self._start_sop_executor_worker(state)

        mentioned_profiles = []
        delegated_payload = step_content
        run_mode = RUN_MODE_EXECUTION
        if state.clarify_mode_enabled:
            state.clarify_phase = CLARIFY_MODE_EXPLORING
            state.clarify_mode_state = CLARIFY_MODE_EXPLORING
            state.pending_clarify_questions = []
            state.clarify_source_user_text = step_content
            state.clarify_answers_context = []
            run_mode = RUN_MODE_CLARIFYING
        self.save_chat_history(session_id=state.session_id)
        self.update_session_tab_title(state.session_id)
        sop_default_profile = self._resolve_sop_default_profile(state)
        if sop_default_profile:
            self.refresh_sop_controls(state.session_id)
            self._dispatch_agent_profiles(
                state,
                step_content,
                delegated_payload,
                [sop_default_profile],
                summon_source="sop_default",
            )
            return True
        template_default_profile = self._resolve_template_default_profile(linked_template)
        if template_default_profile:
            self._dispatch_agent_profiles(
                state,
                step_content,
                delegated_payload,
                [template_default_profile],
                summon_source="automation_template",
            )
            return True
        if not self.daemon_available:
            self.queue_daemon_connection(allow_start=True, retries=4)
        run_context = self._build_run_context(state, run_mode)
        if self.daemon_available:
            self.process_daemon_logic(step_content, turn_id=state.active_turn_id, run_context=run_context, session_id=state.session_id)
        else:
            self.process_agent_logic(step_content, turn_id=state.active_turn_id, run_context=run_context, session_id=state.session_id)
        return True

    def _continue_sop_after_step(self, state, *, create_user_bubble=True):
        if not state:
            return False
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        if not sop_run or is_sop_completed(sop_run):
            self.set_session_phase("Completed", state.session_id)
            self.set_session_status("completed", state.session_id, save=True)
            return False
        if getattr(state, "automation_run_id", ""):
            self._finalize_automation_history_record(
                state.automation_run_id,
                AUTOMATION_HISTORY_STATUS_RUNNING,
                summary=self._automation_summary_from_state(state),
            )
        state.step_records = []
        state.changed_files = []
        state.has_file_changes = False
        state.pending_tool_results = {}
        state.observability_events = []
        state.system_prompt_text = ""
        state.runtime_context_text = ""
        state.prompt_cache_meta = {}
        state.system_prompt_appends = []
        self.refresh_change_list(state.session_id)
        self.refresh_step_list(state.session_id)
        self.refresh_observability_view(state.session_id)
        self.set_context_tab_hint(self.RIGHT_TAB_OBSERVABILITY, True)
        self.set_session_phase("Preparing", state.session_id)
        self.set_session_status("running", state.session_id)
        state.active_turn_id += 1
        state.completed_turn_id = max(state.completed_turn_id, state.active_turn_id - 1)
        linked_template = self._current_sop_template_for_state(state)
        return self._dispatch_current_sop_step(
            state,
            linked_template=linked_template,
            create_user_bubble=create_user_bubble,
            set_running=True,
        )

    def _finalize_sop_execution_step(
        self,
        state,
        *,
        executor="",
        content="",
        agent_profile=None,
        output_status="completed",
        metadata=None,
        allow_auto_advance=True,
    ):
        sop_run = normalize_sop_run(getattr(state, "sop_run", None))
        if not sop_run or is_sop_completed(sop_run):
            return False
        execution_info = {
            "finished_at": int(time.time()),
            "executor": executor or ((sop_run.get("last_execution") or {}).get("executor") or "main_agent"),
            "content": str(content or "").strip(),
        }
        if isinstance(metadata, dict):
            execution_info.update(metadata)
        if agent_profile:
            execution_info["agent_profile_id"] = agent_profile.get("id") or ""
            execution_info["agent_profile_name"] = agent_profile.get("name") or ""
        sop_run = append_step_output(
            sop_run,
            content=content,
            executor=execution_info["executor"],
            status=output_status,
            metadata=metadata,
        )
        advance_mode = resolve_step_advance_mode(sop_run)
        if allow_auto_advance and advance_mode == SOP_ADVANCE_MODE_AUTO:
            state.sop_run = complete_current_step(sop_run, reason="auto_advanced", auto_advanced=True)
            self.save_chat_history(session_id=state.session_id)
            self.refresh_sop_controls(state.session_id)
            self.refresh_context_badges(state.session_id)
            if is_sop_completed(state.sop_run):
                self.set_session_phase("Completed", state.session_id)
                self.set_session_status("completed", state.session_id, save=True)
                return True
            self.set_session_phase("Preparing next step", state.session_id)
            self.set_session_status("running", state.session_id, save=True)
            QTimer.singleShot(0, lambda sid=state.session_id: self._continue_sop_after_step(self.get_session(sid)))
            return True
        state.sop_run = mark_step_awaiting_confirmation(sop_run, execution_info=execution_info)
        self.save_chat_history(session_id=state.session_id)
        self.refresh_sop_controls(state.session_id)
        self.refresh_context_badges(state.session_id)
        self._mark_session_automation_awaiting_confirmation(state)
        self.set_session_phase("Awaiting confirmation", state.session_id)
        self.set_session_status("draft", state.session_id, save=True)
        return True

    def refresh_clarify_controls(self, session_id=None):
        state = self.get_session(session_id)
        if not state or state.session_id != self.current_session_id:
            return
        clarify_enabled = bool(state.clarify_mode_enabled)
        blocked_check = self.clarify_mode_check.blockSignals(True)
        self.clarify_mode_check.setChecked(clarify_enabled)
        self.clarify_mode_check.blockSignals(blocked_check)
        clarify_enabled_for_ui = (
            not ((state.llm_worker and state.llm_worker.isRunning()) or getattr(state, "daemon_running", False))
        )
        self.clarify_mode_check.setEnabled(clarify_enabled_for_ui)
        self.clarify_mode_check.setText("反问模式")
        if hasattr(self, "clarify_mode_badge"):
            self.clarify_mode_badge.setVisible(clarify_enabled)
            self.clarify_mode_badge.setEnabled(clarify_enabled_for_ui)
            blocked_badge = self.clarify_mode_badge.blockSignals(True)
            self.clarify_mode_badge.setChecked(clarify_enabled)
            self.clarify_mode_badge.blockSignals(blocked_badge)
        if hasattr(self, "clarify_mode_action"):
            blocked_action = self.clarify_mode_action.blockSignals(True)
            self.clarify_mode_action.setChecked(clarify_enabled)
            self.clarify_mode_action.blockSignals(blocked_action)
            self.clarify_mode_action.setEnabled(clarify_enabled_for_ui)

    def set_session_phase(self, phase, session_id=None):
        state = self.get_session(session_id)
        if not state:
            return
        state.run_phase = phase
        if state.session_id == self.current_session_id:
            if hasattr(self, "loop_hint"):
                self.loop_hint.setText(phase or "处理中")
            self.refresh_context_badges(state.session_id)

    def _session_has_live_activity(self, session_id):
        state = self.get_session(session_id)
        if not state:
            return False
        return bool(getattr(state, "live_activity", False))

    def refresh_session_activity_indicator(self, session_id):
        indicators = getattr(self, "history_activity_indicators", {})
        indicator = indicators.get(session_id)
        if not indicator:
            return
        running = self._session_has_live_activity(session_id)
        indicator.setRunning(running)
        age_label = getattr(self, "history_age_labels", {}).get(session_id)
        if age_label:
            age_label.setVisible(not running and bool(age_label.text()))

    def set_session_status(self, status, session_id=None, save=False):
        state = self.get_session(session_id)
        if not state:
            return
        state.session_status = status
        if status == "running":
            state.live_activity = True
        elif status in {"completed", "error", "interrupted", "draft"}:
            state.live_activity = False
        if status in {"completed", "error", "interrupted"}:
            self._mark_session_automation_completed(state, status)
        if save and state.messages:
            self.save_chat_history(session_id=state.session_id)
        self.refresh_session_activity_indicator(state.session_id)
        if state.session_id == self.current_session_id:
            self.refresh_context_badges(state.session_id)

    def refresh_change_list(self, session_id=None):
        state = self.get_session(session_id)
        if not state:
            return
        if session_id is None or state.session_id == self.current_session_id:
            self.refresh_context_badges(state.session_id)

    def refresh_step_list(self, session_id=None):
        state = self.get_session(session_id)
        if not state:
            return
        if session_id is None or state.session_id == self.current_session_id:
            self.step_list.clear()
            if not state.step_records:
                item = QListWidgetItem(qta.icon('fa5s.stream', color=DesignTokens.text_tertiary), "本轮工具步骤会显示在这里")
                item.setFlags(Qt.NoItemFlags)
                self.step_list.addItem(item)
                self.step_intro_label.setText("本轮步骤")
            else:
                for record in state.step_records:
                    status = record.get("status") or "running"
                    title = record.get("display_title") or record.get("tool_name") or "Step"
                    summary = record.get("summary") or "Waiting for more output"
                    step_title = record.get("plan_step_title") or ""
                    duration = record.get("duration")
                    duration_text = f" · {duration:.1f}s" if isinstance(duration, (int, float)) else ""
                    line2 = summary
                    if step_title:
                        line2 = f"[步骤] {step_title} | {summary}"
                    icon_name = "fa5s.check-circle" if status == "done" else "fa5s.play-circle"
                    icon_color = DesignTokens.status_success if status == "done" else DesignTokens.status_running
                    item = QListWidgetItem(
                        qta.icon(icon_name, color=icon_color),
                        f"{title} · {status_label_text(status)}{duration_text}\n{line2}",
                    )
                    item.setData(Qt.UserRole, record.get("tool_id"))
                    self.step_list.addItem(item)
                self.step_intro_label.setText(
                    f"本轮已记录 {len(state.step_records)} 个工具步骤"
                )
            self.refresh_context_badges(state.session_id)

    def _observability_pretty_json(self, value):
        try:
            if isinstance(value, str):
                text = value.strip()
                if text.startswith("{") or text.startswith("["):
                    return _safe_text_preview(json.dumps(json.loads(text), indent=2, ensure_ascii=False), 2500)
                return _safe_text_preview(value, 2500)
            text = json.dumps(value, indent=2, ensure_ascii=False)
            return _safe_text_preview(text, 2500)
        except Exception:
            return _safe_text_preview(str(value), 2500)

    def _set_observability_text(self, edit, text, field_name, limit=6000):
        if not _qt_object_alive(edit):
            log_sub_agent_runtime(
                "ui_observability_text_widget_invalid",
                field=field_name,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
            )
            return
        safe_text = _safe_text_preview(text, limit)
        try:
            current_text = edit.toPlainText()
            if current_text == safe_text:
                log_sub_agent_runtime(
                    "ui_observability_text_unchanged",
                    field=field_name,
                    raw_len=len(str(text or "")),
                    safe_len=len(safe_text),
                    current_session_id=str(getattr(self, "current_session_id", "") or ""),
                )
                return
            edit.setPlainText(safe_text)
            log_sub_agent_runtime(
                "ui_observability_text_set",
                field=field_name,
                raw_len=len(str(text or "")),
                safe_len=len(safe_text),
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_text_set_failed",
                field=field_name,
                raw_len=len(str(text or "")),
                traceback=traceback.format_exc(),
            )

    def _format_observability_prompt_append(self, item, index):
        if not isinstance(item, dict):
            return ""
        source = item.get("source") or "system"
        content = item.get("content") or ""
        if not content:
            return ""
        return f"\n\n# 追加系统消息 {index}: {source}\n{content}"

    def _build_observability_prompt_texts(self, state, preview_limit=6000):
        prompt_text = getattr(state, "system_prompt_text", "") or ""
        runtime_context = getattr(state, "runtime_context_text", "") or ""
        prompt_meta = getattr(state, "prompt_cache_meta", {}) or {}
        meta_lines = []
        if isinstance(prompt_meta, dict) and prompt_meta:
            meta_lines = [
                "# Prompt Cache Observability",
                f"prompt_cache_key: {prompt_meta.get('prompt_cache_key') or ''}",
                "",
            ]
        prompt_parts = []
        if meta_lines:
            prompt_parts.append("\n".join(meta_lines))
        if prompt_text:
            prompt_parts.append("# Stable System Prompt\n" + prompt_text)
        if runtime_context:
            prompt_parts.append("# Runtime Context Prompt\n" + runtime_context)
        append_parts = []
        for index, item in enumerate(getattr(state, "system_prompt_appends", []) or [], start=1):
            formatted = self._format_observability_prompt_append(item, index)
            if formatted:
                append_parts.append(formatted)
        full_text = "\n\n".join(prompt_parts) + "".join(append_parts)
        preview_source = "".join(append_parts) if append_parts else full_text
        preview_text = _safe_text_tail_preview(preview_source, preview_limit)
        return full_text, preview_text

    def _observability_time_text(self, ts):
        try:
            if ts is None or ts == "":
                return datetime.now().strftime("%H:%M:%S")
            return datetime.fromtimestamp(float(ts)).strftime("%H:%M:%S")
        except Exception:
            return datetime.now().strftime("%H:%M:%S")

    def _format_observability_event(self, event):
        if not isinstance(event, dict):
            return ""
        event_type = event.get("type") or ""
        stamp = self._observability_time_text(event.get("timestamp"))
        if event_type == "tool_call":
            return (
                f"[{stamp}] CALL {event.get('name') or 'unknown_tool'} ({event.get('id') or ''})\n"
                f"args:\n{self._observability_pretty_json(event.get('args') or {})}"
            )
        if event_type == "tool_result":
            meta = event.get("meta") if isinstance(event.get("meta"), dict) else {}
            duration = meta.get("duration")
            duration_text = f" duration={float(duration):.2f}s" if isinstance(duration, (int, float)) else ""
            result_value = event.get("result_obj") if event.get("result_obj") is not None else event.get("result", "")
            return (
                f"[{stamp}] RESULT {event.get('name') or 'unknown_tool'} ({event.get('id') or ''}){duration_text}\n"
                f"result:\n{self._observability_pretty_json(result_value)}"
            )
        if event_type == "system_prompt_append":
            source = event.get("source") or "system"
            return f"[{stamp}] SYSTEM APPEND {source}\n{event.get('content') or ''}"
        if event_type == "system_prompt":
            cache_key = event.get("prompt_cache_key") or ""
            return f"[{stamp}] SYSTEM PROMPT loaded\nprompt_cache_key={cache_key}"
        if event_type == "llm_usage":
            usage = event.get("usage") if isinstance(event.get("usage"), dict) else {}
            rate = usage.get("cache_hit_rate")
            try:
                rate_text = f"{float(rate) * 100:.1f}%"
            except Exception:
                rate_text = "unknown"
            return (
                f"[{stamp}] LLM USAGE cache_hit={rate_text}\n"
                f"input={usage.get('input_tokens', 'unknown')} "
                f"cached={usage.get('cached_input_tokens', 'unknown')} "
                f"uncached={usage.get('uncached_input_tokens', 'unknown')} "
                f"output={usage.get('output_tokens', 'unknown')} "
                f"total={usage.get('total_tokens', 'unknown')}\n"
                f"prompt_cache_key={usage.get('prompt_cache_key') or ''}"
            )
        return f"[{stamp}] {event_type or 'event'}\n{self._observability_pretty_json(event)}"

    def refresh_observability_view(self, session_id=None):
        try:
            on_ui_thread = QThread.currentThread() is self.thread()
        except RuntimeError:
            on_ui_thread = True
        if not on_ui_thread:
            QTimer.singleShot(0, lambda sid=session_id: self.refresh_observability_view(sid))
            return
        state = self.get_session(session_id)
        if not state or state.session_id != self.current_session_id:
            return
        if not (
            hasattr(self, "observability_prompt_edit")
            and hasattr(self, "observability_log_edit")
            and _qt_object_alive(self.observability_prompt_edit)
            and _qt_object_alive(self.observability_log_edit)
        ):
            log_sub_agent_runtime(
                "ui_observability_widgets_unavailable",
                session_id=getattr(state, "session_id", ""),
            )
            return
        try:
            prompt_joined, prompt_preview = self._build_observability_prompt_texts(state, preview_limit=6000)
            self._set_observability_text(
                self.observability_prompt_edit,
                prompt_preview,
                "system_prompt",
                limit=6000,
            )
            if hasattr(self, "observability_copy_prompt_btn") and _qt_object_alive(self.observability_copy_prompt_btn):
                self.observability_copy_prompt_btn.setEnabled(bool(prompt_joined.strip()))

            log_parts = []
            for event in getattr(state, "observability_events", []) or []:
                if not isinstance(event, dict):
                    continue
                if event.get("type") == "system_prompt":
                    continue
                formatted = self._format_observability_event(event)
                if formatted:
                    log_parts.append(formatted)
            log_joined = "\n\n---\n\n".join(log_parts)
            self._set_observability_text(
                self.observability_log_edit,
                log_joined,
                "event_log",
                limit=10000,
            )
            for edit in (self.observability_prompt_edit, self.observability_log_edit):
                cursor = edit.textCursor()
                cursor.movePosition(QTextCursor.End)
                edit.setTextCursor(cursor)
            log_sub_agent_runtime(
                "ui_observability_refresh_done",
                session_id=state.session_id,
                event_count=len(getattr(state, "observability_events", []) or []),
                prompt_len=len(prompt_joined),
                log_len=len(log_joined),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_refresh_failed",
                session_id=state.session_id,
                traceback=traceback.format_exc(),
            )

    def handle_observability_event(self, data, session_id=None):
        try:
            on_ui_thread = QThread.currentThread() is self.thread()
        except RuntimeError:
            on_ui_thread = True
        if not on_ui_thread:
            payload = dict(data) if isinstance(data, dict) else {}
            QTimer.singleShot(0, lambda p=payload, sid=session_id: self.handle_observability_event(p, sid))
            return
        if not isinstance(data, dict):
            log_sub_agent_runtime(
                "ui_observability_event_invalid",
                session_id=str(session_id or ""),
                data_type=type(data).__name__,
            )
            return
        state = self.get_session(session_id)
        if not state:
            log_sub_agent_runtime(
                "ui_observability_missing_session",
                session_id=str(session_id or ""),
                event_type=data.get("type") or "",
            )
            return
        try:
            event = dict(data)
            event.setdefault("timestamp", time.time())
            event_type = event.get("type") or ""
            if event_type == "system_prompt":
                state.system_prompt_text = event.get("content") or ""
                state.runtime_context_text = event.get("runtime_context") or ""
                state.prompt_cache_meta = {
                    "prompt_cache_key": event.get("prompt_cache_key") or "",
                }
                state.system_prompt_appends = [
                    item for item in (event.get("skill_contexts") or [])
                    if isinstance(item, dict)
                ]
            elif event_type == "system_prompt_append":
                state.system_prompt_appends.append(event)
            state.observability_events.append(event)
            if len(state.observability_events) > 500:
                state.observability_events = state.observability_events[-500:]
            log_sub_agent_runtime(
                "ui_observability_event_recorded",
                session_id=state.session_id,
                event_type=event_type,
                content_len=_sub_agent_payload_content_len(event),
                event_count=len(state.observability_events),
            )
            if state.session_id == self.current_session_id:
                self.set_context_tab_hint(self.RIGHT_TAB_OBSERVABILITY, True)
                self.refresh_observability_view(state.session_id)
                self.refresh_context_badges(state.session_id)
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_event_failed",
                session_id=state.session_id,
                event_type=(data or {}).get("type") or "",
                traceback=traceback.format_exc(),
            )

    def on_step_item_clicked(self, item):
        tool_id = item.data(Qt.UserRole)
        if not tool_id:
            return
        state = self.get_current_session()
        if not state or tool_id not in state.tool_cards:
            return
        card = state.tool_cards[tool_id]
        self.show_tool_details(tool_id, card.args, card.result, meta=card.meta, switch_tab=True)

    def start_background_services(self):
        if self._background_services_started:
            return
        self._background_services_started = True
        self._schedule_background_service_start(BACKGROUND_TRAY_START_DELAY_MS, self.setup_tray)
        self._schedule_background_service_start(BACKGROUND_DAEMON_PREWARM_DELAY_MS, self._start_background_daemon_prewarm)
        self._schedule_background_service_start(BACKGROUND_DAEMON_MONITOR_DELAY_MS, self.start_daemon_monitor)
        self._schedule_background_service_start(BACKGROUND_AUTOMATION_START_DELAY_MS, self.start_automation_scheduler)

    def _schedule_background_service_start(self, delay_ms, callback):
        QTimer.singleShot(max(int(delay_ms or 0), 0), callback)

    def _start_background_daemon_prewarm(self):
        self.setup_daemon_client(retries=6)

    def setup_daemon_client(self, retries=6):
        self.daemon_client = DaemonClient(
            self.daemon_host,
            self.daemon_port,
            timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
        )
        self.queue_daemon_connection(allow_start=True, retries=retries)

    def queue_daemon_connection(self, allow_start=False, retries=0):
        self._pending_daemon_connect_allow_start = bool(
            getattr(self, "_pending_daemon_connect_allow_start", False) or allow_start
        )
        self._pending_daemon_connect_retries = max(
            int(getattr(self, "_pending_daemon_connect_retries", 0) or 0),
            max(0, int(retries or 0)),
        )
        self._drain_daemon_connection_queue()

    def _drain_daemon_connection_queue(self):
        worker = getattr(self, "daemon_connect_worker", None)
        if worker and worker.isRunning():
            self.daemon_bootstrapping = bool(
                getattr(self, "_pending_daemon_connect_allow_start", False) or getattr(worker, "allow_start", False)
            )
            self.refresh_context_badges()
            return
        allow_start = bool(getattr(self, "_pending_daemon_connect_allow_start", False))
        retries = max(0, int(getattr(self, "_pending_daemon_connect_retries", 0) or 0))
        if not allow_start and retries <= 0:
            self.daemon_bootstrapping = False
            self.refresh_context_badges()
            return
        self._pending_daemon_connect_allow_start = False
        self._pending_daemon_connect_retries = 0
        if not self.daemon_client:
            self.daemon_client = DaemonClient(
                self.daemon_host,
                self.daemon_port,
                timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            )
        can_start = allow_start
        if self.daemon_process and self.daemon_process.poll() is None:
            can_start = False
        self.daemon_bootstrapping = bool(allow_start)
        self.refresh_context_badges()
        worker = DaemonConnectWorker(
            self.daemon_host,
            self.daemon_port,
            self.daemon_runtime_signature,
            allow_start=can_start,
            retries=retries,
            timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            parent=self,
        )
        self.daemon_connect_worker = worker
        worker.finished_signal.connect(self.handle_daemon_connect_finished, Qt.QueuedConnection)
        worker.finished.connect(worker.deleteLater)
        worker.start()

    def handle_daemon_connect_finished(self, payload):
        payload = payload if isinstance(payload, dict) else {}
        process = payload.get("process")
        if process is not None:
            self.daemon_process = process
        self.daemon_available = bool(payload.get("connected"))
        self.daemon_connect_worker = None
        self._drain_daemon_connection_queue()

    def start_daemon_monitor(self):
        if self.daemon_timer:
            return
        self.daemon_timer = QTimer(self)
        self.daemon_timer.setInterval(5000)
        self.daemon_timer.timeout.connect(self.ensure_daemon_connection)
        self.daemon_timer.start()

    def ensure_daemon_connection(self):
        self.queue_daemon_connection(allow_start=True, retries=0)

    def start_automation_scheduler(self):
        if self.automation_timer:
            return
        self.automation_timer = QTimer(self)
        self.automation_timer.setInterval(DEFAULT_AUTOMATION_TIMER_INTERVAL_MS)
        self.automation_timer.timeout.connect(self.check_automation_schedules)
        self.automation_timer.start()
        QTimer.singleShot(0, self.check_automation_schedules)

    def _workspace_for_automation(self):
        current = str(self._active_workspace_dir() or "").strip()
        if current and os.path.isdir(current):
            return current
        default_dir = str(self.config_manager.get("default_workspace", "") or "").strip()
        return default_dir if default_dir and os.path.isdir(default_dir) else ""

    def _update_automation_task_record(self, updated_task):
        if not updated_task:
            return
        tasks = self.config_manager.get_automation_tasks()
        target_id = str(updated_task.get("id") or "").strip()
        changed = False
        for index, task in enumerate(tasks):
            if str(task.get("id") or "").strip() != target_id:
                continue
            tasks[index] = updated_task
            changed = True
            break
        if changed:
            self.config_manager.set_automation_tasks(tasks)

    def _append_automation_history(self, record):
        saved = self.config_manager.append_automation_run_history(record)
        if saved and saved.get("status") == AUTOMATION_HISTORY_STATUS_RUNNING:
            self._running_automation_history_ids.add(saved.get("id"))
        return saved

    def _finalize_automation_history_record(self, history_id, status, summary="", error=""):
        history = self.config_manager.get_automation_run_history()
        target_id = str(history_id or "").strip()
        changed = False
        for record in history:
            if str(record.get("id") or "").strip() != target_id:
                continue
            record["status"] = status
            record["finished_at"] = int(time.time())
            if summary:
                record["summary"] = summary
            if error:
                record["error"] = error
            changed = True
            break
        if changed:
            self.config_manager.set_automation_run_history(history)
        self._running_automation_history_ids.discard(target_id)

    def _automation_summary_from_state(self, state):
        if not state:
            return ""
        for message in reversed(getattr(state, "messages", [])):
            if not isinstance(message, dict) or message.get("role") != "assistant":
                continue
            content = str(self._message_display_content(message) or "").strip()
            if content:
                single_line = re.sub(r"\s+", " ", content)
                return single_line[:240]
        return ""

    def _mark_session_automation_completed(self, state, status, error=""):
        if not state or not getattr(state, "automation_run_id", ""):
            return
        summary = self._automation_summary_from_state(state)
        mapped_status = {
            "completed": AUTOMATION_HISTORY_STATUS_COMPLETED,
            "error": AUTOMATION_HISTORY_STATUS_ERROR,
            "interrupted": AUTOMATION_HISTORY_STATUS_INTERRUPTED,
        }.get(status)
        if not mapped_status:
            return
        self._finalize_automation_history_record(state.automation_run_id, mapped_status, summary=summary, error=error)
        task_id = str(state.automation_task_id or "").strip()
        if task_id:
            task = self.config_manager.get_automation_task(task_id)
            if task:
                task["last_run_at"] = int(time.time())
                if state.automation_run_id:
                    task["last_history_id"] = state.automation_run_id
                self._update_automation_task_record(task)
        state.automation_run_id = ""
        state.automation_task_id = ""
        state.automation_trigger_source = ""
        state.automation_template_id = ""

    def run_automation_task_now(self, task_id):
        self._trigger_automation_task(task_id, trigger_source="manual", scheduled_at=0)

    def _trigger_automation_task(self, task_id, trigger_source="scheduler", scheduled_at=0):
        task = self.config_manager.get_automation_task(task_id)
        if not task:
            return False
        template = self.config_manager.get_sop_template(task.get("template_id"))
        if not template:
            record = make_automation_history_record(
                task,
                {},
                status=AUTOMATION_HISTORY_STATUS_ERROR,
                trigger_source=trigger_source,
                scheduled_at=scheduled_at,
                error="任务模板不存在，已跳过执行。",
            )
            self._append_automation_history(record)
            return False
        workspace_dir = self._workspace_for_automation()
        if not workspace_dir:
            record = make_automation_history_record(
                task,
                template,
                status=AUTOMATION_HISTORY_STATUS_ERROR,
                trigger_source=trigger_source,
                scheduled_at=scheduled_at,
                error="未找到可用工作区，请先配置默认工作区。",
            )
            self._append_automation_history(record)
            return False
        session_title = task.get("name") or template.get("name") or "自动化任务"
        session_id = self.create_new_session(title=session_title, make_current=False, workspace_dir=workspace_dir)
        state = self.get_session(session_id)
        if not state:
            return False
        state.selected_skill_names = normalize_selected_skill_names(template.get("skill_names"))
        state.sop_run = create_sop_run(template)
        if state.sop_run:
            state.sop_run["original_user_request"] = build_automation_execution_prompt(task, template)
            state.sop_run["original_display_text"] = task.get("name") or template.get("name") or "自动化任务"
        prompt = build_automation_execution_prompt(task, template)
        history_record = make_automation_history_record(
            task,
            template,
            status=AUTOMATION_HISTORY_STATUS_RUNNING,
            trigger_source=trigger_source,
            session_id=session_id,
            scheduled_at=scheduled_at,
        )
        saved_record = self._append_automation_history(history_record)
        if saved_record:
            state.automation_run_id = saved_record.get("id") or ""
        state.automation_task_id = str(task.get("id") or "")
        state.automation_trigger_source = trigger_source
        state.automation_template_id = str(template.get("id") or "")
        self.activate_session(session_id)
        submitted = self._submit_session_request(
            state,
            prompt,
            [],
            linked_template=template,
            check_duplicates=False,
            clear_current_input=False,
        )
        if not submitted and state.automation_run_id:
            self._finalize_automation_history_record(
                state.automation_run_id,
                AUTOMATION_HISTORY_STATUS_ERROR,
                error="自动化任务未能成功提交。",
            )
            state.automation_run_id = ""
            state.automation_task_id = ""
            state.automation_trigger_source = ""
            state.automation_template_id = ""
            return False
        if trigger_source == "manual":
            self.add_system_toast("自动化任务已启动", "success", session_id=session_id, auto_close_ms=3200)
        return True

    def check_automation_schedules(self):
        tasks = self.config_manager.get_automation_tasks()
        if not tasks:
            return
        now_ts = int(time.time())
        updated_tasks = []
        changed = False
        for task in tasks:
            current = dict(task)
            if not current.get("enabled"):
                updated_tasks.append(current)
                continue
            next_run_at = int(current.get("next_run_at") or 0)
            if not next_run_at:
                current["next_run_at"] = compute_next_run_at(current, now_ts=now_ts)
                current["schedule_summary"] = describe_schedule(current)
                changed = True
                updated_tasks.append(current)
                continue
            if next_run_at + AUTOMATION_RUN_GRACE_SECONDS < now_ts:
                skipped_count = 0
                while current.get("next_run_at") and int(current.get("next_run_at") or 0) + AUTOMATION_RUN_GRACE_SECONDS < now_ts:
                    skipped_count += 1
                    current["last_missed_at"] = int(current.get("next_run_at") or 0)
                    current = advance_task_to_next_run(current, now_ts=now_ts, after_ts=int(current.get("next_run_at") or now_ts))
                    if current.get("schedule_type") == AUTOMATION_SCHEDULE_ONCE:
                        current["enabled"] = False
                        break
                template = self.config_manager.get_sop_template(current.get("template_id"))
                summary = f"应用未运行，已跳过 {skipped_count} 次计划触发。"
                missed_record = make_automation_history_record(
                    current,
                    template,
                    status=AUTOMATION_HISTORY_STATUS_MISSED,
                    trigger_source="scheduler",
                    scheduled_at=next_run_at,
                    summary=summary,
                )
                self._append_automation_history(missed_record)
                current["schedule_summary"] = describe_schedule(current)
                changed = True
                updated_tasks.append(current)
                continue
            if next_run_at <= now_ts:
                triggered = self._trigger_automation_task(current.get("id"), trigger_source="scheduler", scheduled_at=next_run_at)
                current["last_run_at"] = now_ts if triggered else int(current.get("last_run_at") or 0)
                current = advance_task_to_next_run(current, now_ts=now_ts, after_ts=max(now_ts, next_run_at))
                if current.get("schedule_type") == AUTOMATION_SCHEDULE_ONCE:
                    current["enabled"] = False
                current["schedule_summary"] = describe_schedule(current)
                changed = True
            updated_tasks.append(current)
        if changed:
            self.config_manager.set_automation_tasks(updated_tasks)

    def _daemon_signature_matches(self, payload):
        if not isinstance(payload, dict):
            return False
        remote = str(payload.get("signature") or "").strip()
        local = str(getattr(self, "daemon_runtime_signature", "") or "").strip()
        return bool(remote and local and remote == local)

    def try_connect_daemon(self, allow_start=False, retries=0):
        if not self.daemon_client:
            self.daemon_client = DaemonClient(
                self.daemon_host,
                self.daemon_port,
                timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            )
        ping_payload = self.daemon_client.ping()
        connected = bool(ping_payload)
        if connected and not self._daemon_signature_matches(ping_payload):
            try:
                self.daemon_client.shutdown()
            except Exception:
                pass
            time.sleep(0.2)
            connected = False
        if not connected and allow_start:
            self.start_daemon_process()
            for _ in range(max(retries, 0)):
                time.sleep(0.2)
                retry_ping = self.daemon_client.ping()
                if retry_ping and self._daemon_signature_matches(retry_ping):
                    connected = True
                    break
        self.daemon_available = connected
        self.refresh_context_badges()

    def start_daemon_process(self):
        try:
            if self.daemon_process and self.daemon_process.poll() is None:
                return
            self.daemon_process = launch_daemon_subprocess(self.daemon_port)
        except Exception:
            self.daemon_process = None

    def start_gateway_process(self):
        try:
            if getattr(self, "gateway_starting", False):
                return
            if self.gateway_process and self.gateway_process.poll() is None:
                return
            cmd, cwd = build_gateway_launch_command()
            env = os.environ.copy()
            self.gateway_starting = True
            if self.gateway_log_file:
                try:
                    self.gateway_log_file.close()
                except Exception:
                    pass
                self.gateway_log_file = None
            log_path = os.path.join(get_app_data_dir(), "im_gateway.log")
            self.gateway_log_file = open(log_path, "a", encoding="utf-8")
            self.gateway_process = subprocess.Popen(
                cmd,
                cwd=cwd,
                stdout=subprocess.DEVNULL,
                stderr=self.gateway_log_file,
                env=env,
                **subprocess_kwargs_no_window(),
            )
            QTimer.singleShot(GATEWAY_START_SETTLE_DELAY_MS, self._finalize_gateway_startup_state)
        except Exception:
            self.gateway_starting = False
            self.gateway_process = None
            if self.gateway_log_file:
                try:
                    self.gateway_log_file.close()
                except Exception:
                    pass
                self.gateway_log_file = None

    def _finalize_gateway_startup_state(self):
        process = getattr(self, "gateway_process", None)
        if process and process.poll() is not None:
            self.gateway_process = None
            if self.gateway_log_file:
                try:
                    self.gateway_log_file.close()
                except Exception:
                    pass
                self.gateway_log_file = None
        self.gateway_starting = False

    def stop_gateway_process(self):
        self.gateway_starting = False
        if not self.gateway_process:
            return
        self._terminate_process(self.gateway_process)
        self.gateway_process = None
        if self.gateway_log_file:
            try:
                self.gateway_log_file.close()
            except Exception:
                pass
            self.gateway_log_file = None

    def setup_tray(self):
        if not QSystemTrayIcon.isSystemTrayAvailable():
            return
        icon = self.windowIcon()
        if icon.isNull():
            icon = QIcon()
        self.tray_icon = QSystemTrayIcon(icon, self)
        menu = QMenu()
        toggle_action = QAction("显示/隐藏", self)
        toggle_action.triggered.connect(self.toggle_window_visibility)
        status_action = QAction("查看状态", self)
        status_action.triggered.connect(self.show_tray_status)
        quit_action = QAction("退出", self)
        quit_action.triggered.connect(self.quit_app)
        menu.addAction(toggle_action)
        menu.addAction(status_action)
        menu.addSeparator()
        menu.addAction(quit_action)
        self.tray_icon.setContextMenu(menu)
        self.tray_icon.activated.connect(self.on_tray_activated)
        self.tray_icon.show()

    def on_tray_activated(self, reason):
        if reason == QSystemTrayIcon.Trigger:
            self.toggle_window_visibility()

    def toggle_window_visibility(self):
        if self.isVisible():
            self.hide()
        else:
            self.activate_existing_window()

    def activate_existing_window(self):
        if self.isMinimized():
            self.showNormal()
        elif not self.isVisible():
            self.show()
        else:
            self.show()
        self.activateWindow()
        self.raise_()

    def get_daemon_status_text(self):
        if getattr(self, "daemon_bootstrapping", False):
            return "守护进程连接中"
        if getattr(self, "daemon_available", False):
            return "守护进程在线"
        return "守护进程未连接"

    def show_tray_status(self):
        connect_worker = getattr(self, "daemon_connect_worker", None)
        if connect_worker and connect_worker.isRunning():
            status = "守护进程连接中"
            if self.tray_icon:
                self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
            else:
                QMessageBox.information(self, "状态", status)
            return
        if not getattr(self, "daemon_available", False):
            self.queue_daemon_connection(allow_start=True, retries=2)
            status = "正在启动守护进程"
            if self.tray_icon:
                self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
            else:
                QMessageBox.information(self, "状态", status)
            return
        worker = getattr(self, "daemon_status_worker", None)
        if worker and worker.isRunning():
            status = "守护进程状态查询中"
            if self.tray_icon:
                self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
            else:
                QMessageBox.information(self, "状态", status)
            return
        worker = DaemonStatusWorker(
            self.daemon_host,
            self.daemon_port,
            self.daemon_runtime_signature,
            timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            parent=self,
        )
        self.daemon_status_worker = worker
        worker.finished_signal.connect(self.handle_daemon_status_finished, Qt.QueuedConnection)
        worker.finished.connect(worker.deleteLater)
        worker.start()
        status = "正在刷新守护进程状态"
        if self.tray_icon:
            self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 2000)
        else:
            QMessageBox.information(self, "状态", status)

    def handle_daemon_status_finished(self, payload):
        payload = payload if isinstance(payload, dict) else {}
        self.daemon_available = bool(payload.get("connected"))
        self.daemon_status_worker = None
        self.refresh_context_badges()
        status = str(payload.get("status_text") or self.get_daemon_status_text()).strip() or "守护进程状态未知"
        if self.tray_icon:
            self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
        else:
            QMessageBox.information(self, "状态", status)

    def quit_app(self):
        self.shutdown_workers()
        if self.daemon_client:
            self.daemon_client.shutdown()
        self.stop_daemon_process()
        self.stop_gateway_process()
        if self.tray_icon:
            self.tray_icon.hide()
        QApplication.quit()

    def stop_daemon_process(self):
        if not self.daemon_process:
            return
        self._terminate_process(self.daemon_process)
        self.daemon_process = None

    def shutdown_workers(self):
        if not self.flush_pending_chat_saves(timeout_ms=3000):
            self.append_log("会话保存队列在关闭前未能完全 flush，应用将继续退出。")
        deliverable_scan_worker = getattr(self, "deliverable_scan_worker", None)
        if deliverable_scan_worker is not None and deliverable_scan_worker.isRunning():
            deliverable_scan_worker.wait(3000)
        self.deliverable_scan_worker = None
        if self.daemon_connect_worker and self.daemon_connect_worker.isRunning():
            self.daemon_connect_worker.wait(1000)
        self.daemon_connect_worker = None
        if self.daemon_status_worker and self.daemon_status_worker.isRunning():
            self.daemon_status_worker.wait(1000)
        self.daemon_status_worker = None
        for session_id, state in list(self.sessions.items()):
            for guidance_worker in list(getattr(state, "guidance_workers", []) or []):
                try:
                    guidance_worker.wait(500)
                except Exception:
                    pass
            state.guidance_workers = []
            self._stop_live_subagents(state, force=True)
            if self.daemon_client and state.daemon_running and state.session_id:
                try:
                    self.daemon_client.stop_session(state.session_id)
                except Exception:
                    pass
            if state.daemon_worker and state.daemon_worker.isRunning():
                self._disconnect_worker_signals(state.daemon_worker)
                state.daemon_worker.abort()
                state.daemon_worker.wait(1000)
            if state.llm_worker and state.llm_worker.isRunning():
                self._disconnect_worker_signals(state.llm_worker)
                state.llm_worker.stop()
                state.llm_worker.wait(1000)
            if state.code_worker and state.code_worker.isRunning():
                self._disconnect_worker_signals(state.code_worker)
                state.code_worker.stop()
                state.code_worker.wait(1000)
            state.daemon_running = False
            state.daemon_worker = None
            state.llm_worker = None
            state.code_worker = None
        if self.daemon_timer:
            self.daemon_timer.stop()
        if getattr(self, "chat_save_worker", None):
            if not self.chat_save_worker.stop_worker(timeout_ms=3000):
                self.append_log("会话保存线程未在超时内退出。")
            self.chat_save_worker = None

    def _terminate_process(self, proc):
        if not proc:
            return
        try:
            if proc.poll() is None:
                proc.terminate()
                proc.wait(timeout=2)
        except Exception:
            pass
        if proc.poll() is None and platform.system() == "Windows":
            try:
                subprocess.run(
                    ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    **subprocess_kwargs_no_window(),
                )
            except Exception:
                pass
        try:
            if proc.poll() is None:
                proc.kill()
        except Exception:
            pass

    def closeEvent(self, event):
        if self.tray_icon:
            event.ignore()
            self.hide()
            self.tray_icon.showMessage("DeepSeek Cowork", "已最小化到托盘", QSystemTrayIcon.Information, 2000)
        else:
            self.shutdown_workers()
            self.stop_daemon_process()
            self.stop_gateway_process()
            event.accept()

    def attach_single_instance_server(self, server):
        self.single_instance_server = server
            
    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, 'drag_overlay'):
            self.drag_overlay.resize(self.size())
        if hasattr(self, "right_sidebar"):
            self.position_context_drawer()
        self._position_active_system_toast()

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
            if hasattr(self, 'drag_overlay'):
                self.drag_overlay.show()
                self.drag_overlay.raise_()
        else:
            event.ignore()

    def dragLeaveEvent(self, event):
        if hasattr(self, 'drag_overlay'):
            self.drag_overlay.hide()

    def dropEvent(self, event):
        if hasattr(self, 'drag_overlay'):
            self.drag_overlay.hide()
            
        if event.mimeData().hasUrls():
            urls = event.mimeData().urls()
            if not urls: return
            
            path = urls[0].toLocalFile()
            if os.path.isdir(path):
                # Switch workspace
                self.load_workspace(path)
            else:
                self._add_prompt_files([path])
            
            event.acceptProposedAction()

    # --- Session & Logic Methods (No changes to logic, only UI wrappers) ---
    def get_current_session(self):
        if not self.current_session_id: return None
        return self.sessions.get(self.current_session_id)

    def get_session(self, session_id=None):
        if session_id is None: return self.get_current_session()
        return self.sessions.get(session_id)

    def sync_current_session_state(self):
        state = self.get_current_session()
        if not state: return
        state.messages = self.messages
        state.tool_cards = self.tool_cards
        state.pending_tool_results = self.pending_tool_results
        state.current_content_buffer = self.current_content_buffer
        state.current_thinking_buffer = self.current_thinking_buffer
        state.last_flushed_content_buffer = getattr(self, "last_flushed_content_buffer", "")

    def set_current_session(self, session_id):
        state = self.sessions.get(session_id)
        if not state: return
        self.current_session_id = session_id
        self.messages = state.messages
        self.tool_cards = state.tool_cards
        self.pending_tool_results = getattr(state, "pending_tool_results", {})
        self.current_content_buffer = state.current_content_buffer
        self.current_thinking_buffer = getattr(state, "current_thinking_buffer", "")
        self.last_flushed_content_buffer = getattr(state, "last_flushed_content_buffer", "")
        self.temp_thinking_bubble = state.temp_thinking_bubble
        self.last_agent_bubble = state.last_agent_bubble
        self.llm_worker = state.llm_worker
        self.code_worker = state.code_worker
        self.chat_layout = state.chat_layout
        self.active_skills_label = state.active_skills_label
        self.current_deliverable_path = getattr(state, "selected_deliverable_path", "") or ""
        self.refresh_change_list(session_id)
        self.refresh_step_list(session_id)
        self.refresh_observability_view(session_id)
        self.refresh_context_badges(session_id)
        self.refresh_sop_controls(session_id)
        self.refresh_selected_skill_controls(session_id)
        self.refresh_prompt_file_chips(session_id)
        if (
            getattr(state, "history_loaded", True)
            and getattr(self, "right_drawer_open", False)
            and getattr(self, "right_drawer_tab", None) == self.RIGHT_TAB_SUB_AGENTS
        ):
            self._queue_render_sub_agent_monitor_for_state(state)
        self._sync_workspace_ui_for_session(session_id, refresh_sidebar=False)
        if (
            getattr(self, "right_drawer_open", False)
            and getattr(self, "right_drawer_tab", None) == self.RIGHT_TAB_DELIVERABLES
        ):
            self.refresh_deliverables(render_current=True)

    def normalize_session_ui(self, state):
        if not state: return
        running = state.llm_worker and state.llm_worker.isRunning()
        paused = running and state.llm_worker.is_paused
        running_code = state.code_worker and state.code_worker.isRunning()
        running_daemon = getattr(state, "daemon_running", False)
        
        if running or running_code or running_daemon:
            self.action_btn.setText("停止")
            self.action_btn.setIcon(qta.icon('fa5s.stop', color='white'))
            self.action_btn.setStyleSheet("background-color: #ef4444; color: white; border-radius: 18px; font-weight: bold; border: none;")
            self.action_btn.setEnabled(True)
            self.input_field.setEnabled(False)
            
            # Hide extra buttons/prompts when running
            self.pause_btn.setVisible(False)
            self.loop_hint.setVisible(False)
        else:
            self.action_btn.setText("发送")
            self.action_btn.setIcon(qta.icon('fa5s.paper-plane', color='white'))
            self.action_btn.setStyleSheet("background-color: #4d6bfe; color: white; border-radius: 18px; font-weight: bold; border: none;")
            self.action_btn.setEnabled(True)
            self.input_field.setEnabled(True)
            
            self.pause_btn.setVisible(False)
            self.loop_hint.setVisible(False)

    def normalize_session_ui(self, state):
        if not state:
            return
        history_ready = session_history_ready(state)
        running = state.llm_worker and state.llm_worker.isRunning()
        paused = running and state.llm_worker.is_paused
        running_code = state.code_worker and state.code_worker.isRunning()
        running_daemon = getattr(state, "daemon_running", False)

        if running or running_code or running_daemon:
            steerable = bool(getattr(state, "turn_steerable", False) and not running_code)
            self.action_btn.setText("引导" if steerable else "运行中")
            self.action_btn.setIcon(qta.icon('fa5s.paper-plane', color='white'))
            self.action_btn.setStyleSheet(apple_button_style("primary", radius=20))
            self.action_btn.setEnabled(steerable)
            self.input_field.setEnabled(steerable)
            self.tool_menu_btn.setEnabled(steerable)
            self.stop_btn.setVisible(True)
            if steerable:
                self.input_field.setPlaceholderText("输入补充说明，将在当前任务的下一个安全节点生效")
            self.pause_btn.setVisible(bool(running))
            loop_text = getattr(state, "run_phase", "") or ("处理中" if (running_daemon or running_code) else "")
            self.loop_hint.setText(loop_text or "处理中")
            self.loop_hint.setToolTip(loop_text or "处理中")
            self.loop_hint.setVisible(bool(running_daemon or running_code or loop_text))
            if paused:
                self.pause_btn.setIcon(qta.icon('fa5s.play', color=DesignTokens.success_text))
                self.pause_btn.setToolTip("继续")
            else:
                self.pause_btn.setIcon(qta.icon('fa5s.pause', color=DesignTokens.text_secondary))
                self.pause_btn.setToolTip("暂停")
        else:
            awaiting_sop_confirmation = is_sop_awaiting_confirmation(getattr(state, "sop_run", None))
            idle_text = "等待确认" if awaiting_sop_confirmation else ("开始反问" if state.clarify_mode_enabled else "开始")
            self.action_btn.setText(idle_text)
            self.action_btn.setIcon(qta.icon('fa5s.paper-plane', color='white'))
            self.action_btn.setStyleSheet(apple_button_style("primary", radius=20))
            workspace_dir = self._workspace_dir_for_state(state)
            self.action_btn.setEnabled(history_ready)
            self.input_field.setEnabled(history_ready)
            self.tool_menu_btn.setEnabled(bool(workspace_dir) and history_ready)
            self.tool_menu_btn.setToolTip("" if workspace_dir else "连接项目后可添加文件、自动化和本地能力")
            self.stop_btn.setVisible(False)
            if not history_ready:
                self.input_field.setPlaceholderText("正在加载历史会话，请稍候…")
                self.action_btn.setText("加载中")
            if awaiting_sop_confirmation:
                self.input_field.setPlaceholderText("请先在聊天中的自动化确认条处理当前步骤")
            elif workspace_dir:
                self.input_field.setPlaceholderText("描述你要完成的任务，例如：整理本周截图并生成周报摘要")
            else:
                self.input_field.setPlaceholderText("直接开始对话；需要处理文件时再连接项目")
            self.pause_btn.setVisible(False)
            self.loop_hint.setVisible(False)
        self.refresh_selected_skill_controls(state.session_id)
        self.refresh_project_selector(state.session_id)
        self.refresh_context_badges(state.session_id)
        self.refresh_observability_view(state.session_id)
        self.update_skill_capture_button_state()

    def get_session_id_for_tab(self, index):
        widget = self.session_tabs.widget(index)
        if not widget: return None
        for session_id, state in self.sessions.items():
            if state.session_widget == widget: return session_id
        return None

    def close_session_tab(self, index):
        session_id = self.get_session_id_for_tab(index)
        if not session_id: return
        state = self.sessions.get(session_id)
        if state:
            self._stop_live_subagents(state, force=True)
            if state.daemon_worker:
                self._disconnect_worker_signals(state.daemon_worker)
                try:
                    state.daemon_worker.abort()
                except Exception:
                    pass
            if state.llm_worker:
                self._disconnect_worker_signals(state.llm_worker)
                try:
                    state.llm_worker.stop()
                except Exception:
                    pass
            if state.code_worker:
                self._disconnect_worker_signals(state.code_worker)
                try:
                    state.code_worker.stop()
                except Exception:
                    pass
            del self.sessions[session_id]
        self.session_tabs.removeTab(index)
        if self.session_tabs.count() == 0: self.create_new_session()

    def on_session_tab_changed(self, index):
        self.sync_current_session_state()
        session_id = self.get_session_id_for_tab(index)
        if session_id:
            self.activate_session(session_id, switch_tab=False, ensure_loaded=True)

    def clear_chat_layout(self, chat_layout):
        while chat_layout.count():
            item = chat_layout.takeAt(0)
            widget = item.widget()
            if widget is not None: widget.deleteLater()
        chat_layout.addStretch()

    def _compute_session_title(self, messages):
        title = "新对话"
        for msg in messages:
            if msg.get("role") == "user":
                content = self._message_display_content(msg).strip()
                if not content:
                    attachments = self._message_user_attachments(msg)
                    if attachments:
                        content = attachments[0].get("name") or attachments[0].get("path") or ""
                if content: title = content[:15] + "..." if len(content) > 15 else content
                break
        return title

    def update_session_tab_title(self, session_id):
        state = self.sessions.get(session_id)
        if not state: return
        title = self._compute_session_title(state.messages)
        index = self.session_tabs.indexOf(state.session_widget)
        if index >= 0: self.session_tabs.setTabText(index, title)

    def create_new_session(self, session_id=None, title=None, make_current=True, workspace_dir=None):
        is_fresh_session = session_id is None
        if session_id is None: session_id = uuid.uuid4().hex
        session_widget = QWidget()
        session_widget.setStyleSheet("background: transparent;")
        session_layout = QVBoxLayout(session_widget)
        session_layout.setContentsMargins(0, 0, 0, 0)
        session_layout.setSpacing(10)

        active_skills_label = QLabel("本次会话使用的功能: ")
        active_skills_label.setStyleSheet("color: #9ca3af; font-size: 11px; margin-left: 12px;")
        active_skills_label.setVisible(False)
        session_layout.addWidget(active_skills_label)

        chat_scroll = QScrollArea()
        chat_scroll.setWidgetResizable(True)
        chat_scroll.setStyleSheet("QScrollArea { border: none; background: transparent; }")
        chat_container = QWidget()
        chat_container.setStyleSheet("background: transparent;")
        chat_layout = QVBoxLayout(chat_container)
        chat_layout.setContentsMargins(22, 18, 26, 22)
        chat_layout.setSpacing(10)
        
        # Add Empty State
        empty_state = EmptyStateWidget(self)
        chat_layout.addWidget(empty_state)
        
        chat_layout.addStretch()
        chat_scroll.setWidget(chat_container)
        session_layout.addWidget(chat_scroll, 1)

        tab_title = title or "新对话"
        tab_index = self.session_tabs.addTab(session_widget, tab_title)
        self.session_tabs.tabBar().hide()

        state = SessionState(session_id, chat_layout, active_skills_label, session_widget, chat_scroll)
        state.content_flush_timer = QTimer(self)
        state.content_flush_timer.setSingleShot(True)
        state.content_flush_timer.setInterval(CONTENT_FLUSH_INTERVAL_MS)
        state.content_flush_timer.timeout.connect(lambda sid=session_id: self.flush_session_content(sid))
        state.thinking_flush_timer = QTimer(self)
        state.thinking_flush_timer.setSingleShot(True)
        state.thinking_flush_timer.setInterval(THINKING_FLUSH_INTERVAL_MS)
        state.thinking_flush_timer.timeout.connect(lambda sid=session_id: self.flush_session_thinking(sid))
        state.scroll_flush_timer = QTimer(self)
        state.scroll_flush_timer.setSingleShot(True)
        state.scroll_flush_timer.setInterval(SCROLL_FLUSH_INTERVAL_MS)
        state.scroll_flush_timer.timeout.connect(lambda sid=session_id: self.flush_session_scroll(sid))
        state.virtualization_timer = QTimer(self)
        state.virtualization_timer.setSingleShot(True)
        state.virtualization_timer.setInterval(90)
        state.virtualization_timer.timeout.connect(lambda sid=session_id: self.virtualize_session_bubbles(sid))
        chat_scroll.verticalScrollBar().valueChanged.connect(lambda value, sid=session_id: self.on_chat_scroll_value_changed(value, sid))
        state.empty_state = empty_state
        state.history_loaded = is_fresh_session
        self._set_session_workspace(state, workspace_dir if workspace_dir is not None else self._active_workspace_dir())
        self.sessions[session_id] = state
        if make_current:
            self.session_tabs.setCurrentIndex(tab_index)
            self.set_current_session(session_id)
            self.refresh_change_list(session_id)
            self.refresh_step_list(session_id)
            self.refresh_context_badges(session_id)
        return session_id

    def _reset_session_history_state(self, state):
        self.clear_chat_layout(state.chat_layout)
        state.empty_state = None
        state.prompt_files = []
        state.messages = []
        state.render_items = []
        state.tool_cards = {}
        state.pending_tool_results = {}
        state.current_content_buffer = ""
        state.current_thinking_buffer = ""
        state.last_flushed_content_buffer = ""
        state.pending_thinking_delta = ""
        state.temp_thinking_bubble = None
        state.last_agent_bubble = None
        state.llm_worker = None
        state.live_activity = False
        state.auto_scroll_enabled = True
        state.pending_scroll_force = False
        state.active_turn_id = 0
        state.completed_turn_id = 0
        state.active_skills_label.setText("本次会话使用的功能: ")
        state.active_skills_label.setVisible(False)
        state.displayed_count = 0
        state.displayed_render_count = 0
        state.load_more_btn = None
        state.clarify_mode_enabled = False
        state.clarify_phase = CLARIFY_MODE_DISABLED
        state.clarify_mode_state = CLARIFY_MODE_EXPLORING
        state.pending_clarify_questions = []
        state.clarify_source_user_text = ""
        state.clarify_answers_context = []
        state.selected_skill_names = []
        state.sop_run = None
        state.sop_confirmation_bar = None
        state.persisted_conversation_meta = {}
        state.completed_agent_result_ids = set()
        state.automation_task_id = ""
        state.automation_run_id = ""
        state.automation_trigger_source = ""
        state.automation_template_id = ""
        state.changed_files = []
        state.step_records = []
        state.persisted_agents = []
        state.sub_agent_events = []
        state.sub_agent_history_loaded = False
        state.virtualization_active = False

    def _show_session_loading_state(self, state, text="正在加载历史会话…"):
        self.clear_chat_layout(state.chat_layout)
        state.empty_state = None
        placeholder = QLabel(text)
        placeholder.setAlignment(Qt.AlignCenter)
        placeholder.setStyleSheet(
            f"color: {DesignTokens.text_secondary}; font-size: 13px; padding: 32px 0;"
        )
        state.chat_layout.insertWidget(0, placeholder)

    def _rebuild_session_render_spans(self, state):
        state.render_items = build_conversation_render_spans(state.messages)
        state.displayed_count = len(state.messages)
        state.displayed_render_count = min(
            max(int(getattr(state, "displayed_render_count", 0) or 0), 0),
            len(state.render_items),
        )

    def _render_session_history_spans(self, state, spans, insert_index=None):
        if not state or not spans:
            return
        start = spans[0].get("start", 0)
        end = spans[-1].get("end", start)
        if end <= start:
            return
        self.render_message_batch(
            state.messages[start:end],
            state.session_id,
            insert_index=insert_index,
            animate=False,
        )

    def _render_initial_session_history(self, state):
        spans = getattr(state, "render_items", []) or []
        if not spans:
            empty_state = EmptyStateWidget(self)
            state.chat_layout.insertWidget(0, empty_state)
            state.empty_state = empty_state
            state.displayed_render_count = 0
            return
        total = len(spans)
        start_idx = max(0, total - HISTORY_RENDER_PAGE_SIZE)
        initial_spans = spans[start_idx:]
        state.displayed_render_count = len(initial_spans)
        self._render_session_history_spans(state, initial_spans)
        self.queue_session_bubble_virtualization(state.session_id)

    def activate_session(self, session_id, switch_tab=True, ensure_loaded=True):
        state = self.sessions.get(session_id)
        if state is None:
            self.create_new_session(session_id=session_id, make_current=False)
            state = self.sessions.get(session_id)
            if not state:
                return
            state.history_loaded = False
            self._show_session_loading_state(state)
            try:
                meta = self.chat_storage.get_conversation_meta(session_id)
            except Exception:
                meta = {}
            self._set_session_workspace(state, (meta or {}).get("workspace_dir"))

        index = self.session_tabs.indexOf(state.session_widget)
        if switch_tab and index >= 0 and self.session_tabs.currentIndex() != index:
            self.session_tabs.setCurrentIndex(index)

        self.set_current_session(session_id)
        self.update_history_selection()
        self.refresh_change_list(session_id)
        self.refresh_step_list(session_id)
        current_state = self.get_current_session()
        self.normalize_session_ui(current_state)
        if (
            current_state
            and getattr(current_state, "history_loaded", True)
            and getattr(self, "right_drawer_open", False)
            and getattr(self, "right_drawer_tab", None) == self.RIGHT_TAB_SUB_AGENTS
        ):
            self._queue_render_sub_agent_monitor_for_state(current_state)

        if ensure_loaded and not state.history_loaded and not state.history_loading:
            self.queue_session_history_load(session_id)

    def queue_session_history_load(self, session_id):
        state = self.get_session(session_id)
        if not state:
            return
        self._session_load_token_counter += 1
        state.history_load_token = self._session_load_token_counter
        state.history_loading = True
        self._show_session_loading_state(state)
        if session_id == self.current_session_id:
            self.normalize_session_ui(state)
        QTimer.singleShot(
            0,
            lambda sid=session_id, token=state.history_load_token: self._load_session_history(sid, token)
        )

    def _load_session_history(self, session_id, token):
        state = self.get_session(session_id)
        if not state or token != state.history_load_token:
            return

        self._reset_session_history_state(state)
        loaded_from_json = False
        conversation_meta = {}
        conversation_record = None
        try:
            conversation_meta = self.chat_storage.get_conversation_meta(session_id)
        except Exception:
            conversation_meta = {}
        try:
            conversation_record = self.chat_storage.get_conversation_record(session_id)
        except Exception:
            conversation_record = None

        state.session_status = (
            (conversation_record or {}).get("status")
            or conversation_meta.get("session_status")
            or "draft"
        )
        state.persisted_conversation_meta = copy.deepcopy(conversation_meta or {})
        state.run_phase = conversation_meta.get("run_phase") or "Idle"
        state.has_file_changes = bool(conversation_meta.get("has_file_changes"))
        state.selected_skill_names = normalize_selected_skill_names(
            conversation_meta.get("selected_skill_names")
        )
        state.sop_run = normalize_sop_run(conversation_meta.get("sop_run"))
        state.clarify_mode_enabled = bool(conversation_meta.get("clarify_mode_enabled"))
        state.clarify_mode_state = normalize_clarify_phase(
            conversation_meta.get("clarify_mode_state"),
            default=CLARIFY_MODE_EXPLORING,
        )
        state.pending_clarify_questions = normalize_pending_clarify_questions(
            conversation_meta.get("pending_clarify_questions")
        )
        state.clarify_phase = normalize_clarify_phase(
            conversation_meta.get("clarify_phase"),
            default=derive_clarify_phase(
                state.clarify_mode_enabled,
                state.clarify_mode_state,
            ),
        )

        try:
            state.messages = self.chat_storage.get_messages(session_id)
        except Exception:
            state.messages = []
        try:
            state.persisted_agents = self.chat_storage.list_agents(session_id)
        except Exception:
            state.persisted_agents = []
        state.sub_agent_events = []
        state.sub_agent_history_loaded = False
        if not state.messages:
            history_path = os.path.join(self.chat_history_dir, f'chat_history_{session_id}.json')
            if os.path.exists(history_path):
                try:
                    with open(history_path, 'r', encoding='utf-8') as f:
                        state.messages = json.load(f)
                    loaded_from_json = True
                except Exception as e:
                    print(f"Error loading session: {e}")

        if state.messages:
            state.messages = self._normalize_and_persist_session_messages(
                session_id,
                state.messages,
                force_persist=loaded_from_json,
                existing_meta=conversation_meta
            )
        self._rebuild_session_render_spans(state)
        self._render_initial_session_history(state)

        self._finish_session_history_load(state)
        self.update_session_tab_title(session_id)
        self.update_history_selection()
        self.refresh_change_list(session_id)
        self.refresh_step_list(session_id)
        self.normalize_session_ui(self.get_current_session())
        self.refresh_sop_controls(session_id)
        self.refresh_selected_skill_controls(session_id)
        if session_id == self.current_session_id:
            self._queue_render_sub_agent_monitor_for_state(state)

    def _finish_session_history_load(self, state):
        if not state:
            return
        state.history_loaded = True
        state.history_loading = False
        if state.session_id == self.current_session_id:
            # Loading replaces the per-session containers. Rebind the window-level
            # aliases so a later tab sync cannot write the pre-load empty objects
            # back over the restored conversation.
            self.set_current_session(state.session_id)

    def load_session(self, session_id):
        self.activate_session(session_id)

    def show_interaction_dialog(self, request):
        request = dict(request or {})
        kind = (request.get("kind") or "approval").strip().lower()
        title = (request.get("title") or "需要你的输入").strip()
        message = request.get("message") or ""
        metadata = request.get("metadata") if isinstance(request.get("metadata"), dict) else {}
        options = request.get("options") if isinstance(request.get("options"), list) else []
        questions = request.get("questions") if isinstance(request.get("questions"), list) else []
        questions = normalize_pending_clarify_questions(questions)
        allow_free_text = bool(request.get("allow_free_text"))

        dialog = QDialog(self)
        dialog.setWindowTitle(title or "需要你的输入")
        dialog.resize(520, 420)
        layout = QVBoxLayout(dialog)

        scroll_area = QScrollArea()
        scroll_area.setWidgetResizable(True)
        scroll_area.setFrameShape(QFrame.NoFrame)
        content_widget = QWidget()
        content_layout = QVBoxLayout(content_widget)
        label = QLabel(message)
        label.setWordWrap(True)
        label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        label.setStyleSheet("font-size: 14px; line-height: 1.4;")
        content_layout.addWidget(label)

        details = (metadata.get("details") or "").strip()
        if details:
            details_label = QLabel(details)
            details_label.setWordWrap(True)
            details_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
            details_label.setStyleSheet(f"color: {DesignTokens.text_secondary}; font-size: 12px;")
            content_layout.addWidget(details_label)
        content_layout.addStretch()
        scroll_area.setWidget(content_widget)
        layout.addWidget(scroll_area)

        hint_text = "请完成这一步操作。"
        if kind == "approval":
            severity = (metadata.get("severity") or "medium").strip().lower()
            hint_text = {
                "high": "这是高风险操作，请明确选择继续或取消。",
                "low": "请确认是否继续执行。",
            }.get(severity, "请确认是否继续执行。")
        elif kind == "choice":
            hint_text = "请选择一个选项，必要时可以补充自由文本。"
        elif kind == "multi_choice":
            hint_text = "请选择一个或多个选项，必要时可以补充自由文本。"
        elif kind == "questionnaire":
            hint_text = "请逐题选择，必要时可以补充文本。"
        elif kind == "text":
            hint_text = "请输入你要补充给 AI 的信息。"
        hint_label = QLabel(hint_text)
        hint_label.setStyleSheet(f"color: {DesignTokens.text_secondary}; font-size: 13px;")
        layout.addWidget(hint_label)

        input_field = QLineEdit()
        input_field.setPlaceholderText("输入补充内容…")
        input_field.setVisible(kind == "text" or ((kind in {"choice", "multi_choice"}) and allow_free_text))
        layout.addWidget(input_field)

        option_combo = None
        option_checks = []
        question_controls = []
        if kind == "choice" and options:
            option_combo = QComboBox()
            option_combo.addItem("请选择…", "")
            for idx, option in enumerate(options, start=1):
                label_text = (option.get("label") or option.get("value") or f"Option {idx}").strip()
                value = (option.get("value") or label_text).strip()
                option_combo.addItem(f"{idx}. {label_text}", value)
            layout.addWidget(option_combo)
        elif kind == "multi_choice" and options:
            option_group = QGroupBox("选项")
            option_layout = QVBoxLayout(option_group)
            for idx, option in enumerate(options, start=1):
                label_text = (option.get("label") or option.get("value") or f"Option {idx}").strip()
                value = (option.get("value") or label_text).strip()
                description = (option.get("description") or "").strip()
                checkbox = QCheckBox(f"{idx}. {label_text}" + (f" - {description}" if description else ""))
                checkbox.setProperty("option_value", value)
                option_checks.append(checkbox)
                option_layout.addWidget(checkbox)
            layout.addWidget(option_group)
        elif kind == "questionnaire" and questions:
            question_scroll = QScrollArea()
            question_scroll.setWidgetResizable(True)
            question_scroll.setFrameShape(QFrame.NoFrame)
            question_wrap = QWidget()
            question_layout = QVBoxLayout(question_wrap)
            question_layout.setContentsMargins(0, 0, 0, 0)
            question_layout.setSpacing(12)
            for question_item in questions:
                q_group = QGroupBox(str(question_item.get("header") or "问题"))
                q_layout = QVBoxLayout(q_group)
                q_text = QLabel(str(question_item.get("question") or ""))
                q_text.setWordWrap(True)
                q_text.setStyleSheet(f"color: {DesignTokens.text_primary};")
                q_layout.addWidget(q_text)
                q_combo = QComboBox()
                q_combo.addItem("请选择…", "")
                for idx, q_option in enumerate(question_item.get("options") or [], start=1):
                    q_label = (q_option.get("label") or "").strip()
                    q_value = (q_option.get("value") or q_label).strip()
                    if not q_label:
                        continue
                    q_combo.addItem(f"{idx}. {q_label}", q_value)
                q_layout.addWidget(q_combo)
                q_input = QLineEdit()
                q_input.setPlaceholderText("可选：补充说明")
                q_input.setVisible(bool(allow_free_text))
                q_layout.addWidget(q_input)
                question_controls.append(
                    {
                        "id": question_item.get("id"),
                        "combo": q_combo,
                        "input": q_input,
                    }
                )
                question_layout.addWidget(q_group)
            question_layout.addStretch()
            question_scroll.setWidget(question_wrap)
            layout.addWidget(question_scroll, 1)

        button_layout = QHBoxLayout()
        button_layout.addStretch()
        submit_btn = QPushButton("提交")
        yes_btn = QPushButton("继续")
        no_btn = QPushButton("取消")
        submit_btn.setStyleSheet(f"background: {DesignTokens.primary}; color: white; border: none; border-radius: 6px; padding: 6px 14px;")
        yes_btn.setStyleSheet(f"background: {DesignTokens.bg_secondary}; color: {DesignTokens.text_primary}; border: 1px solid {DesignTokens.border}; border-radius: 6px; padding: 6px 14px;")
        no_btn.setStyleSheet(f"background: transparent; color: {DesignTokens.text_secondary}; border: 1px solid {DesignTokens.border}; border-radius: 6px; padding: 6px 14px;")
        if kind == "approval":
            button_layout.addWidget(yes_btn)
            button_layout.addWidget(no_btn)
        else:
            button_layout.addWidget(submit_btn)
            button_layout.addWidget(no_btn)
        layout.addLayout(button_layout)
        decision = {"value": False}

        def selected_values():
            values = []
            if option_combo is not None:
                combo_value = (option_combo.currentData() or "").strip()
                if combo_value:
                    values.append(combo_value)
            for checkbox in option_checks:
                if checkbox.isChecked():
                    option_value = (checkbox.property("option_value") or "").strip()
                    if option_value:
                        values.append(option_value)
            return values

        def on_submit():
            text = input_field.text().strip()
            picked = selected_values()
            if kind == "text":
                if not text:
                    QMessageBox.information(dialog, "提示", "请先输入内容。")
                    input_field.setFocus()
                    return
                decision["value"] = text
                dialog.accept()
                return
            if kind == "choice":
                if picked:
                    decision["value"] = picked[0]
                    dialog.accept()
                    return
                if allow_free_text and text:
                    decision["value"] = text
                    dialog.accept()
                    return
                QMessageBox.information(dialog, "提示", "请先选择一个选项或输入内容。")
                return
            if kind == "multi_choice":
                if picked:
                    if allow_free_text and text:
                        picked = picked + [text]
                    decision["value"] = picked
                    dialog.accept()
                    return
                if allow_free_text and text:
                    decision["value"] = [text]
                    dialog.accept()
                    return
                QMessageBox.information(dialog, "提示", "请先选择至少一个选项或输入内容。")
                return
            if kind == "questionnaire":
                answers = {}
                for control in question_controls:
                    question_id = str(control.get("id") or "").strip()
                    combo_widget = control.get("combo")
                    input_widget = control.get("input")
                    selected = ""
                    text_value = ""
                    if combo_widget is not None:
                        selected = str(combo_widget.currentData() or "").strip()
                    if input_widget is not None:
                        text_value = input_widget.text().strip()
                    if not selected and not text_value:
                        continue
                    answers[question_id] = {
                        "selected_options": [selected] if selected else [],
                        "text": text_value,
                        "raw_value": selected or text_value,
                    }
                if not answers:
                    QMessageBox.information(dialog, "提示", "请至少回答一个问题。")
                    return
                decision["value"] = answers
                dialog.accept()
                return

        def on_yes():
            decision["value"] = True
            dialog.accept()

        def on_no():
            decision["value"] = False
            dialog.reject()

        submit_btn.clicked.connect(on_submit)
        yes_btn.clicked.connect(on_yes)
        no_btn.clicked.connect(on_no)
        input_field.returnPressed.connect(on_submit)
        if input_field.isVisible():
            input_field.setFocus()
        dialog.exec()
        return decision["value"]

    def handle_interaction_request(self, request):
        state = self.get_current_session()
        if state:
            self.set_session_phase("Awaiting input", state.session_id)
        result = self.show_interaction_dialog(request)
        bridge.resolve_request((request or {}).get("request_id"), result)
    
    def handle_daemon_interaction_request(self, request, session_id=None):
        self.set_session_phase("Awaiting input", session_id)
        result = self.show_interaction_dialog(request)
        if self.daemon_client:
            self.daemon_client.respond_interaction((request or {}).get("request_id"), result)

    def refresh_history_list(self):
        self.history_container.setUpdatesEnabled(False)
        while self.history_layout.count():
            item = self.history_layout.takeAt(0)
            if item.widget(): item.widget().deleteLater()
        
        conversations = self.chat_storage.list_conversations()
        conversation_ids = {c["id"] for c in conversations}

        for conv in conversations:
            session_id = conv["id"]
            title = conv["title"] or "新对话"
            if conv.get("im_provider") == "feishu":
                ts = conv.get("updated_at")
                if ts:
                    title = f"飞书对话 {datetime.fromtimestamp(ts).strftime('%Y-%m-%d')}"
                else:
                    title = "飞书对话"
            row = QWidget()
            row_layout = QHBoxLayout(row)
            row_layout.setContentsMargins(0, 0, 0, 0)
            row_layout.setSpacing(8)
            btn = HistoryTitleButton(title)
            btn.setCursor(Qt.PointingHandCursor)
            if session_id == self.current_session_id:
                 btn.setStyleSheet("text-align: left; padding: 10px; border: none; border-radius: 8px; background-color: #eff6ff; color: #1d4ed8; font-weight: 600;")
            else:
                 btn.setStyleSheet("text-align: left; padding: 10px; border: none; border-radius: 8px; background-color: transparent; color: #4b5563;")
            btn.clicked.connect(lambda checked=False, sid=session_id: self.load_session(sid))
            del_btn = QPushButton()
            del_btn.setIcon(qta.icon('fa5s.trash-alt', color='#ef4444'))
            del_btn.setCursor(Qt.PointingHandCursor)
            del_btn.setFixedSize(28, 28)
            del_btn.setStyleSheet("border: none; background: transparent;")
            del_btn.clicked.connect(lambda checked=False, sid=session_id: self.delete_session(sid))
            row_layout.addWidget(btn, 1)
            row_layout.addWidget(del_btn, 0, Qt.AlignRight | Qt.AlignVCenter)
            self.history_layout.addWidget(row)

        history_dir = self.chat_history_dir
        if os.path.exists(history_dir):
            files = glob.glob(os.path.join(history_dir, 'chat_history_*.json'))
            files.sort(key=os.path.getmtime, reverse=True)

            for file_path in files:
                try:
                    filename = os.path.basename(file_path)
                    session_id = filename.replace('chat_history_', '').replace('.json', '')
                    if session_id in conversation_ids:
                        continue
                    with open(file_path, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                        if not data: continue
                        title = self._compute_session_title(data)
                        row = QWidget()
                        row_layout = QHBoxLayout(row)
                        row_layout.setContentsMargins(0, 0, 0, 0)
                        row_layout.setSpacing(8)
                        btn = HistoryTitleButton(title)
                        btn.setCursor(Qt.PointingHandCursor)
                        if session_id == self.current_session_id:
                             btn.setStyleSheet("text-align: left; padding: 10px; border: none; border-radius: 8px; background-color: #eff6ff; color: #1d4ed8; font-weight: 600;")
                        else:
                             btn.setStyleSheet("text-align: left; padding: 10px; border: none; border-radius: 8px; background-color: transparent; color: #4b5563;")
                        btn.clicked.connect(lambda checked=False, sid=session_id: self.load_session(sid))
                        del_btn = QPushButton()
                        del_btn.setIcon(qta.icon('fa5s.trash-alt', color='#ef4444'))
                        del_btn.setCursor(Qt.PointingHandCursor)
                        del_btn.setFixedSize(28, 28)
                        del_btn.setStyleSheet("border: none; background: transparent;")
                        del_btn.clicked.connect(lambda checked=False, sid=session_id: self.delete_session(sid))
                        row_layout.addWidget(btn, 1)
                        row_layout.addWidget(del_btn, 0, Qt.AlignRight | Qt.AlignVCenter)
                        self.history_layout.addWidget(row)
                except Exception as e:
                    continue
        self.history_layout.addStretch()
        self.history_container.setUpdatesEnabled(True)
        self.history_container.update()

    def _history_query_text(self):
        field = getattr(self, "history_search_input", None)
        return (field.text() if field else "").strip()

    def _history_group_title(self, updated_at):
        if not updated_at:
            return "更早"
        try:
            item_date = datetime.fromtimestamp(int(updated_at)).date()
        except Exception:
            return "更早"
        today = datetime.now().date()
        if item_date == today:
            return "今天"
        if item_date == today - timedelta(days=1):
            return "昨天"
        if item_date >= today - timedelta(days=7):
            return "近 7 天"
        return "更早"

    def _history_time_text(self, updated_at):
        if not updated_at:
            return ""
        try:
            dt = datetime.fromtimestamp(int(updated_at))
        except Exception:
            return ""
        if dt.date() == datetime.now().date():
            return dt.strftime("%H:%M")
        return dt.strftime("%m-%d %H:%M")

    def _normalize_project_path(self, path):
        text = str(path or "").strip()
        if not text:
            return ""
        return os.path.normpath(os.path.abspath(os.path.expanduser(text)))

    def _project_key(self, path):
        normalized = self._normalize_project_path(path)
        return os.path.normcase(normalized)

    def _project_display_name(self, path, project_meta=None):
        if isinstance(project_meta, dict) and str(project_meta.get("name") or "").strip():
            return str(project_meta.get("name") or "").strip()
        normalized = self._normalize_project_path(path)
        return os.path.basename(normalized.rstrip(os.sep)) or normalized or "未命名项目"

    def _format_project_session_age(self, updated_at):
        if not updated_at:
            return ""
        try:
            dt = datetime.fromtimestamp(int(updated_at))
        except Exception:
            return ""
        now = datetime.now()
        if dt.date() == now.date():
            minutes = max(1, int((now - dt).total_seconds() // 60))
            if minutes < 60:
                return f"{minutes} 分"
            return f"{max(1, minutes // 60)} 时"
        days = max(1, (now.date() - dt.date()).days)
        if days < 7:
            return f"{days} 天"
        weeks = max(1, days // 7)
        return f"{weeks} 周"

    def _conversation_workspace_path(self, conversation):
        meta = (conversation or {}).get("meta") or {}
        return self._normalize_project_path(meta.get("workspace_dir"))

    def _workspace_dir_for_state(self, state=None):
        if state is None:
            current_session_id = getattr(self, "current_session_id", "")
            sessions = getattr(self, "sessions", {}) or {}
            state = sessions.get(current_session_id) if current_session_id else None
        if not state:
            return self._normalize_project_path(getattr(self, "workspace_dir", ""))
        workspace_dir = self._normalize_project_path(getattr(state, "workspace_dir", ""))
        if workspace_dir:
            return workspace_dir
        meta = getattr(state, "persisted_conversation_meta", {}) or {}
        if isinstance(meta, dict):
            workspace_dir = self._normalize_project_path(meta.get("workspace_dir"))
            if workspace_dir:
                state.workspace_dir = workspace_dir
                return workspace_dir
        return ""

    def _workspace_dir_for_session_id(self, session_id):
        return self._workspace_dir_for_state(self.get_session(session_id))

    def _set_session_workspace(self, state, workspace_dir):
        if not state:
            return ""
        normalized = self._normalize_project_path(workspace_dir)
        state.workspace_dir = normalized
        meta = copy.deepcopy(getattr(state, "persisted_conversation_meta", {}) or {})
        if normalized:
            meta["workspace_dir"] = normalized
        else:
            meta.pop("workspace_dir", None)
        state.persisted_conversation_meta = meta
        return normalized

    def _apply_workspace_to_ui(self, directory, refresh_sidebar=True, remember_workspace=False, persist_default=False):
        directory = self._normalize_project_path(directory)
        self.workspace_dir = directory
        self.current_project_path = directory
        display_path = "未选择"
        tooltip = ""
        if directory:
            font_metrics = QFontMetrics(self.ws_label.font())
            display_path = font_metrics.elidedText(directory, Qt.ElideMiddle, 400)
            tooltip = directory
        self.ws_label.setText(f"当前项目：{display_path}")
        self.ws_label.setToolTip(tooltip)
        if directory and remember_workspace:
            self.update_recent_workspaces(directory)
        if directory and persist_default:
            self.config_manager.set("default_workspace", directory)
        self.update_ui_state_for_workspace()

        if hasattr(self, 'file_model'):
            self.file_model.setRootPath(directory)
            self.file_tree.setRootIndex(self.file_model.index(directory))
            self.set_context_tab_hint(self.RIGHT_TAB_FILES, bool(directory))
            self.set_context_tab_hint(self.RIGHT_TAB_DELIVERABLES, bool(directory))
            self.refresh_deliverables()
        if refresh_sidebar:
            self.refresh_history_list()
        return directory

    def _sync_workspace_ui_for_session(self, session_id=None, refresh_sidebar=True):
        state = self.get_session(session_id)
        workspace_dir = self._workspace_dir_for_state(state)
        return self._apply_workspace_to_ui(
            workspace_dir,
            refresh_sidebar=refresh_sidebar,
            remember_workspace=False,
            persist_default=False,
        )

    def _active_workspace_dir(self):
        current = self._workspace_dir_for_state()
        if current:
            return current
        candidate = self._normalize_project_path(getattr(self, "current_project_path", "") or getattr(self, "workspace_dir", ""))
        if candidate and os.path.isdir(candidate):
            return candidate
        return ""

    def _sidebar_visible_project_paths(self):
        paths = []
        for path, row in self.project_rows.items():
            if row and row.isVisible():
                paths.append(path)
        return paths

    def _add_history_group_label(self, text):
        label = QLabel(text)
        label.setStyleSheet(apple_history_group_style())
        self.history_layout.addWidget(label)

    def _add_history_empty_state(self, text):
        label = QLabel(text)
        label.setWordWrap(True)
        label.setAlignment(Qt.AlignCenter)
        label.setStyleSheet(
            f"color: {DesignTokens.text_tertiary}; font-size: 12px; padding: 28px 12px;"
        )
        self.history_layout.addWidget(label)

